 15	/// Canonicalize `path`, falling back to canonicalizing its parent directory
 16	/// and rejoining the file name when the full path can't be resolved (e.g. the
 17	/// file doesn't exist yet — created and then immediately edited before this
 18	/// session ever saw it read successfully). Falls back to `path` unchanged only
 19	/// when even the parent doesn't exist. Deliberately stable across a file's
 20	/// create/delete transitions: the parent directory is what actually needs a
 21	/// consistent identity across repeated `update_file` calls for the same file,
 22	/// not the file itself.
 23	fn canonicalize_best_effort(path: &Utf8Path) -> Utf8PathBuf {
 24	    if let Ok(p) = std::fs::canonicalize(path.as_std_path()) {
 25	        if let Ok(p) = Utf8PathBuf::from_path_buf(p) {
 26	            return p;
 27	        }
 28	    }
 29	    if let (Some(parent), Some(file_name)) = (path.parent(), path.file_name()) {
 30	        if let Ok(p) = std::fs::canonicalize(parent.as_std_path()) {
 31	            if let Ok(mut p) = Utf8PathBuf::from_path_buf(p) {
 32	                p.push(file_name);
