153	    /// Handle a single file change — re-resolve only affected components.
154	    pub fn update_file(&self, changed: &Utf8Path) -> IncrementalUpdate {
155	        let start = Instant::now();
156	
157	        // `discover_files`'s directory walk (via the `ignore` crate) resolves
158	        // symlinks in the paths it reports — e.g. macOS's `/var` -> `/private/var`
159	        // — so every path already stored in `global`/`reverse_deps` is in that
160	        // resolved form. A file-watcher-reported `changed` path is not
161	        // guaranteed to match unless it's canonicalized the same way; without
162	        // this, `reverse_deps.affected()` below would look up the wrong key and
163	        // silently find no dependents at all.
164	        let changed = canonicalize_best_effort(changed);
165	        let changed = changed.as_path();
166	
167	        // 1. Re-parse the changed file.
168	        let mut io_diagnostic: Option<Diagnostic> = None;
169	        let source = match std::fs::read_to_string(changed) {
170	            Ok(s) => s,
171	            Err(e) => {
172	                io_diagnostic = Some(Diagnostic::io_read_error(changed, &e));
173	                String::new()
174	            }
175	        };
176	        let mut new_data = crate::extractor::parse_file(changed, &source);
177	        // Drained here as in the cold path's merge, so both paths cache and merge the same `SourceData`.
178	        let parse_diagnostics = std::mem::take(&mut new_data.diagnostics);
179	
180	        // 2. Patch GlobalSourceData atomically using rcu (read-copy-update).
181	        // rcu retries if the pointer was swapped by a concurrent update_file call,
182	        // preventing lost-update races under parallel file change events.
183	        // rcu's return value is the PRE-swap value (arc-swap's compare_and_swap
184	        // convention), not the value the closure just produced — the closure's
185	        // result must be re-read via load_full() to see the post-update state.
186	        self.global.rcu(|old| {
187	            let mut g = (**old).clone();
188	            g.remove_file(changed);
189	            g.merge(changed, new_data.clone());
190	            g
191	        });
192	        let new_global = self.global.load_full();
193	
194	        // Keep the named-type index in sync with `global`'s own unconditional
195	        // per-file patch above (same remove-then-merge shape, same lack of a
196	        // read-failure gate — this index derives from `global`, not from
197	        // `component_cache`'s separately-decided AC-019 persistence policy).
198	        // `Arc::make_mut` mutates in place when this call holds the only
199	        // reference (the common case), and clones only if a concurrent
200	        // `update_file` call is still using the previous snapshot.
201	        let named_types = {
202	            let mut guard = self.named_types.lock().unwrap_or_else(|p| p.into_inner());
203	            let index = Arc::make_mut(&mut guard);
204	            index.remove_file(changed);
205	            index.merge_file(&new_data);
206	            guard.clone()
207	        };
208	
209	        // 3. Find all transitively affected files via the reverse dep graph, rebuilt from the post-edit imports so an
210	        // edge this edit added (or removed) is already reflected.
211	        self.reverse_deps.store(Arc::new(ReverseDeps::build(&new_global)));
212	        let affected = self.reverse_deps.load().affected(changed);
213	
214	        // 4. Re-resolve affected components.
215	        // Borrowed, not cloned — same reasoning as the one-shot `extract()`
216	        // path's identical fix (pipeline/mod.rs): `resolve_component` already
217	        // takes `&ComponentMapping`, and `.par_iter()` below only ever
218	        // produces borrows anyway.
219	        let affected_mappings: Vec<&ComponentMapping> =
220	            new_global.component_mappings.iter().filter(|m| affected.contains(&m.file_path)).collect();
221	
222	        let ambient_global_files = self.ambient_global_files.get().cloned().unwrap_or_default();
223	        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
224	            new_global.clone(),
225	            &self.options,
226	            ambient_global_files,
227	            named_types,
228	        );
229	        let results = super::resolve_guarded(&affected_mappings, &ctx);
230	
231	        // A failed read (deletion, permission error, non-UTF8 content) must
232	        // NOT evict this file's cache entries — SPEC-PIPELINE-001's AC-019
233	        // deliberately specifies that a deleted file's previously-resolved
234	        // component stays in component_cache/snapshot() until a new
235	        // WatchSession is constructed, a documented (not accidental)
236	        // staleness gap distinct from the rename case below. Only a
237	        // successful re-read, which can genuinely produce a different set of
238	        // component names for this file, should evict what it no longer owns.
239	        let file_read_failed = io_diagnostic.is_some();
240	
241	        let mut updated_components = Vec::new();
242	        let mut diagnostics: Vec<Diagnostic> = io_diagnostic.into_iter().chain(parse_diagnostics).collect();
243	
244	        // Evict every existing component_cache entry that belonged to this
245	        // file — by whatever key it was stored under, bare or disambiguated —
246	        // before inserting its freshly-resolved entries. A bare `insert(
247	        // entry.display_name, ...)` here left two kinds of stale entries
248	        // behind forever: a renamed component's old-name key never got
249	        // removed, and a disambiguated key from initialize()'s cold Phase 5
250	        // pass was never touched by an update that only ever wrote the bare
251	        // key. Both traced to the same root cause — no eviction step existed
252	        // at all. This resolves the file's keys as a batch first so a
253	        // same-file rename doesn't race against its own insert below.
254	        if !file_read_failed {
255	            let stale_keys: Vec<String> = self
256	                .component_cache
257	                .iter()
258	                .filter(|r| r.value().file_path == changed)
259	                .map(|r| r.key().clone())
260	                .collect();
261	            for key in stale_keys {
262	                self.component_cache.remove(&key);
263	            }
264	        }
265	
266	        for ((entry, diags), mapping) in results.into_iter().zip(&affected_mappings) {
267	            if let Some(note) = super::unresolved_wrapper_guess(mapping, &entry) {
268	                diagnostics.extend(diags);
269	                diagnostics.push(note);
270	                continue;
271	            }
272	            // Disambiguate against whatever's left in the cache after this
273	            // file's own stale keys were just evicted above — mirrors Phase
274	            // 5's bare-then-disambiguated rule (extract()'s one-shot path),
275	            // checked incrementally instead of via a session-wide counter.
276	            // Deliberately narrower than Phase 5 in one respect: if a rename
277	            // elsewhere frees up a bare key another file's component was
278	            // disambiguated against earlier, that other entry stays under
279	            // its disambiguated key until its own file is next touched —
280	            // still correctly retrievable, just not repacked to the
281	            // now-available bare key. Re-optimizing every other cached
282	            // entry's key on every single-file edit would defeat the point
283	            // of incremental updates; only this file's own stale keys are
284	            // this method's responsibility.
285	            let key = if self.component_cache.iter().any(|r| r.value().display_name == entry.display_name) {
286	                format!("{} ({})", entry.display_name, entry.file_path)
287	            } else {
288	                entry.display_name.clone()
289	            };
290	            self.component_cache.insert(key, entry.clone());
291	            updated_components.push(entry);
292	            diagnostics.extend(diags);
293	        }
294	
295	        // Replace (not append) this file's diagnostics — a fixed file's prior
296	        // errors shouldn't linger in subsequent snapshots.
297	        if diagnostics.is_empty() {
298	            self.diagnostics.remove(changed);
299	        } else {
300	            self.diagnostics.insert(changed.to_owned(), diagnostics.clone());
301	        }
302	
303	        IncrementalUpdate {
304	            updated_components,
305	            affected_files: affected.into_iter().collect(),
306	            diagnostics,
307	            duration_ms: start.elapsed().as_millis() as u64,
308	        }
309	    }
310	}
