173	        source: r#"
174	            import type { MissingProps } from "./missing";
175	            export const Ghost = wrap<HTMLDivElement, MissingProps>("div");
176	        "#,
177	        expect: &[],
178	    },
179	    Case {
180	        shape: "async and untyped functions",
181	        source: r#"
182	            interface P { label?: string }
183	            export const Load = async (props: P) => null;
184	            export const Untyped = (props) => <div />;
185	            export const Sum = (a: number, b: number) => a + b;
186	            export const helper = (props: P) => props.label;
187	        "#,
188	        expect: &[],
189	    },
190	];
191	
192	/// Extra files some cases import from, written next to every case's source.
193	const SUPPORT: &[(&str, &str)] = &[
194	    ("barrel/index.ts", "export type { Shared } from \"./shared\";\n"),
195	    ("barrel/shared.ts", "export interface Shared { shared?: string }\n"),
196	];
197	
198	fn run(case: &Case) -> BTreeMap<String, Vec<String>> {
199	    let tmp = tempfile::TempDir::new().unwrap();
200	    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(tmp.path()).unwrap()).unwrap();
201	    for (name, body) in SUPPORT {
202	        let path = root.join(name);
203	        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
204	        std::fs::write(path, body).unwrap();
205	    }
206	    // `./barrel` in the case source resolves from the case file's directory.
207	    std::fs::write(root.join("case.tsx"), case.source.replace("\"./barrel\"", "\"./barrel/index\"")).unwrap();
208	    let options =
209	        PipelineOptions { src_dirs: vec![root.clone()], cache_dir: Some(root.join(".cache")), ..Default::default() };
210	    extract(&options)
211	        .components
212	        .into_iter()
213	        .map(|(name, entry)| (name, entry.props.keys().cloned().collect()))
214	        .collect()
215	}
216	
217	#[test]
218	fn every_declaration_shape_yields_exactly_the_expected_components_and_props() {
219	    let mut failures = Vec::new();
220	    for case in CASES {
221	        let got = run(case);
222	        let want: BTreeMap<String, Vec<String>> = case
223	            .expect
224	            .iter()
225	            .map(|(name, props)| ((*name).to_owned(), props.iter().map(|p| (*p).to_owned()).collect()))
226	            .collect();
227	        if got != want {
228	            failures.push(format!("{}:\n    want {want:?}\n    got  {got:?}", case.shape));
229	        }
230	    }
231	    assert!(failures.is_empty(), "shape regressions:\n{}", failures.join("\n"));
232	}

