251	                        && !self.try_record_wrapper_call(declarator, &name)
252	                    {
253	                        self.record_skip(
254	                            DiagnosticCode::SkippedCandidate,
255	                            format!(
256	                                "'{name}' is a PascalCase binding but matched no known component pattern \
257	                                 (FC annotation, forwardRef, HOC wrapper, or identifier alias)"
258	                            ),
259	                            declarator.span,
260	                        );
261	                    }
262	                }
263	            }
264	            // Pattern 5: declare const Button: React.ForwardRefExoticComponent<ButtonProps & RefAttributes<E>>
265	            // Common in .d.ts files — no initializer, just a type annotation
266	            if declarator.init.is_none() {
267	                if let Some(name) = self.extract_pascal_name(declarator) {
268	                    if let Some(mapping) = self.try_forward_ref_exotic_decl(declarator, &name) {
269	                        self.data.component_mappings.push(mapping);
270	                    } else if self.type_annotation_is_fc_family(declarator) {
271	                        // try_fc_annotation already ran unconditionally above and found
272	                        // nothing — the annotation is FC-shaped but its props type
273	                        // argument is an exotic TSType this extractor doesn't match.
274	                        self.record_skip(
275	                            DiagnosticCode::SkippedCandidate,
276	                            format!(
277	                                "'{name}' is a PascalCase declaration with an FC-family type annotation whose \
278	                                 props type argument isn't a recognizable type"
279	                            ),
280	                            declarator.span,
281	                        );
282	                    }
283	                }
284	            }
