293	                let name = id.name.as_str();
294	                if is_pascal_case(name) && func.r#type == FunctionType::FunctionDeclaration {
295	                    if let Some(first_param) = func.params.items.first() {
296	                        if let Some(type_ann) = &first_param.type_annotation {
297	                            if let Some((props_name, type_args)) =
298	                                self.extract_type_name_from_type(&type_ann.type_annotation)
299	                            {
300	                                let (description, tags) = self.find_jsdoc_with_tags(func.span.start);
301	                                let param_defaults = self.extract_param_defaults(&func.params);
302	                                self.data.component_mappings.push(
303	                                    ComponentMapping::new(
304	                                        name.to_owned(),
305	                                        props_name,
306	                                        self.file_path.clone(),
307	                                        func.span.start,
308	                                        func.span.end,
309	                                        DetectionRule::FunctionDeclaration,
310	                                    )
311	                                    .with_props_type_args(type_args)
312	                                    .with_doc(description, tags)
313	                                    .with_param_defaults(param_defaults),
314	                                );
315	                            } else {
316	                                self.record_skip(
317	                                    DiagnosticCode::SkippedCandidate,
318	                                    format!(
319	                                        "'{name}' is a PascalCase function declaration whose first param's type \
320	                                         annotation isn't a recognizable props type reference"
321	                                    ),
322	                                    type_ann.span,
323	                                );
324	                            }
325	                        } else {
326	                            self.record_skip(
327	                                DiagnosticCode::SkippedCandidate,
328	                                format!("'{name}' is a PascalCase function declaration with an untyped first param"),
329	                                first_param.span,
330	                            );
331	                        }
332	                    }
333	                }
334	            }
335	        }
