339	    fn visit_class(&mut self, class: &Class<'a>) {
340	        // `class Button extends React.Component<Props> { ... }` — shared entry
341	        // point for both a ClassDeclaration and a self-named ClassExpression;
342	        // an anonymous ClassExpression (no `class.id`) is instead picked up by
343	        // `try_class_expression_wrapped` in `visit_variable_declaration`'s
344	        // detector chain, from the outer binding's name.
345	        if self.is_tsx {
346	            if let Some(id) = &class.id {
