351	                            self.data.component_mappings.push(mapping);
352	                        } else if class.heritage.as_ref().is_some_and(|h| h.type_arguments.is_some()) {
353	                            // Extends Component/PureComponent WITH type args, but the
354	                            // props argument itself is an exotic shape
355	                            // extract_type_name_from_type doesn't match. No type args
356	                            // at all is left silent — mirrors visit_function's Pattern 4
357	                            // zero-params contract (a genuinely untyped candidate, not a
358	                            // malformed one).
359	                            self.record_skip(
360	                                DiagnosticCode::SkippedCandidate,
361	                                format!(
362	                                    "'{name}' is a class component extending {family} whose props type \
363	                                     argument isn't a recognizable props type reference"
364	                                ),
365	                                class.span,
366	                            );
367	                        }
368	                    }
369	                }
370	            }
371	        }
372	        walk::walk_class(self, class);
373	    }
