 40	/// Stateful session for incremental watch-mode extraction.
 41	///
 42	/// `global`, `reverse_deps`, and `component_cache` are updated atomically /
 43	/// concurrently on each file change. `reverse_deps` is rebuilt from the merged
 44	/// import graph after every edit, so an import added or removed by an edit
 45	/// takes effect for the next one.
 46	pub struct WatchSession {
 47	    pub options: PipelineOptions,
 48	    /// Current merged source data — swapped atomically via `ArcSwap`.
 49	    pub global: ArcSwap<GlobalSourceData>,
 50	    /// Reverse-dependency graph, rebuilt from the merged `global` by `initialize()` and again by every `update_file`.
 51	    pub reverse_deps: ArcSwap<ReverseDeps>,
 52	    /// Latest resolved component entries, keyed by display name.
 53	    pub component_cache: DashMap<String, ComponentEntry>,
 54	    /// Latest diagnostics per file, replaced (not appended) on each re-update so a
 55	    /// fixed file's stale diagnostics don't linger — mirrors GlobalSourceData::remove_file's
 56	    /// per-file replacement semantics.
 57	    pub diagnostics: DashMap<Utf8PathBuf, Vec<Diagnostic>>,
 58	    /// TypeScript's own lib.d.ts paths, computed once here at `initialize()`
 59	    /// rather than by every `ResolutionContext::new` inside `update_file` —
 60	    /// `options.src_dirs` (the only input this depends on) never changes
 61	    /// within a session, so re-walking the filesystem for it on every single
 62	    /// file save would be pure waste.
 63	    ambient_global_files: std::sync::OnceLock<Vec<Utf8PathBuf>>,
 64	    /// Guards initialize() so concurrent callers don't race to build caches.
 65	    initialized: Mutex<bool>,
 66	    /// Fast `(file, name)` interface/type-alias index — mirrors `self.global`'s
 67	    /// incremental per-file patching (`remove_file` + merge on each edit)
 68	    /// rather than being rebuilt from the whole project on every
 69	    /// `update_file` call. `Mutex<Arc<_>>` (not `ArcSwap`, unlike `global`):
 70	    /// `update_file` mutates it in place via `Arc::make_mut` when nothing else
 71	    /// still holds a reference (the common case — no full clone needed), and
 72	    /// falls back to cloning only if a concurrent call is still using the
 73	    /// previous snapshot. `ArcSwap::rcu` can't express "mutate in place when
 74	    /// possible" — its closure always produces a brand new value.
 75	    named_types: Mutex<Arc<crate::named_type_index::NamedTypeIndex>>,
 76	}
 77	
 78	impl WatchSession {
 79	    /// Create an empty WatchSession (call `initialize()` before first use).
 80	    pub fn new(options: PipelineOptions) -> Self {
 81	        Self {
 82	            options,
 83	            global: ArcSwap::new(Arc::new(GlobalSourceData::default())),
 84	            reverse_deps: ArcSwap::new(Arc::new(ReverseDeps { inner: Default::default() })),
 85	            component_cache: DashMap::new(),
 86	            diagnostics: DashMap::new(),
 87	            ambient_global_files: std::sync::OnceLock::new(),
 88	            initialized: Mutex::new(false),
 89	            named_types: Mutex::new(Arc::new(crate::named_type_index::NamedTypeIndex::default())),
 90	        }
 91	    }
 92	
 93	    /// Run a full cold extraction to populate this session's caches.
 94	    ///
 95	    /// Idempotent — concurrent or repeated calls return the existing snapshot
 96	    /// without re-running extraction.
 97	    pub fn initialize(&self) -> ExtractionOutput {
 98	        let mut guard = self.initialized.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
 99	        if *guard {
100	            return self.snapshot();
101	        }
102	
103	        // Single real pipeline run (discover, parse, merge, Full-mode
104	        // @types/react, ambient lib.d.ts, resolve) shared with the one-shot
105	        // extract() path — see extract_with_global's doc comment. Previously
106	        // this rebuilt GlobalSourceData by hand here, which skipped the
107	        // Full-mode/ambient-lib.d.ts merges entirely: the cold `output` below
108	        // was correct (it came from a real extract() call), but the `global`
109	        // this session persists for every subsequent update_file() was not.
110	        let (output, global, _per_file_data) = super::extract_with_global(&self.options, true);
111	
112	        self.ambient_global_files.set(crate::resolver::compute_ambient_global_files(&self.options)).ok();
113	        self.reverse_deps.store(Arc::new(ReverseDeps::build(&global)));
114	        *self.named_types.lock().unwrap_or_else(|p| p.into_inner()) =
115	            Arc::new(crate::named_type_index::NamedTypeIndex::build(&global));
116	        self.global.store(global);
117	
118	        // Seed component cache from the cold output.
119	        for (name, entry) in &output.components {
120	            self.component_cache.insert(name.clone(), entry.clone());
121	        }
122	
123	        *guard = true;
124	        output
125	    }
126	
127	    /// Return the current full extraction state from the in-memory caches.
128	    /// Suitable for writing to `--out` after each incremental update.
129	    pub fn snapshot(&self) -> ExtractionOutput {
130	        let components: std::collections::BTreeMap<String, ComponentEntry> =
131	            self.component_cache.iter().map(|r| (r.key().clone(), r.value().clone())).collect();
132	        let global = self.global.load();
133	        let (enums, enum_diagnostics) = super::collect_public_enums(&global);
134	
135	        // DashMap iteration order is arbitrary — sort by path for deterministic output.
136	        let mut by_path: Vec<(Utf8PathBuf, Vec<Diagnostic>)> =
137	            self.diagnostics.iter().map(|r| (r.key().clone(), r.value().clone())).collect();
138	        by_path.sort_by(|a, b| a.0.cmp(&b.0));
139	        let diagnostics: Vec<Diagnostic> = by_path.into_iter().flat_map(|(_, ds)| ds).chain(enum_diagnostics).collect();
140	
141	        // Only `components_extracted` is populated here — the other ExtractionStats
142	        // fields (files_parsed, dts_cache_hits, duration_ms, tier1/tier3/opaque
143	        // counts) describe a single extract() run's own bookkeeping, which this
144	        // session doesn't accumulate across incremental update_file() calls. A
145	        // consumer reading watch --out's stats block for anything but the
146	        // component count sees zeros — a known, narrower gap than reporting
147	        // componentsExtracted itself as 0 regardless of how many components exist.
148	        let stats = ExtractionStats { components_extracted: components.len() as u32, ..ExtractionStats::default() };
149	
150	        ExtractionOutput { components, enums, diagnostics, stats }
151	    }
