191	/// Shared implementation for `extract()` and `WatchSession::initialize()`.
192	/// Runs every phase (discover, parse, merge, Full-mode `@types/react`,
193	/// ambient lib.d.ts, resolve) exactly once and hands back everything a caller
194	/// might need beyond the public-facing output: the fully-merged
195	/// `GlobalSourceData` (so watch mode doesn't have to hand-rebuild a second,
196	/// easily-incomplete one just for incremental updates — see `WatchSession`'s
197	/// prior bug, where its own rebuild skipped the Full-mode/ambient-lib.d.ts
198	/// merges entirely) and each file's own parsed `SourceData` (so watch mode can
199	/// seed its per-file cache without re-parsing). `capture_source_data` is
200	/// `false` for the one-shot `extract()` path, which never looks at the third
201	/// tuple element — skip the extra per-file clone in that case.
202	pub(crate) fn extract_with_global(
203	    options: &PipelineOptions,
204	    capture_source_data: bool,
205	) -> (ExtractionOutput, Arc<GlobalSourceData>, Vec<(Utf8PathBuf, SourceData)>) {
206	    let start = Instant::now();
207	    let mut diagnostics = Vec::new();
208	
209	    // Phase 0: Validate that configured source directories exist. A typo'd --src (or a
210	    // stale docgen.config.ts srcDirs) must not silently produce an empty-but-valid-looking
211	    // result — see AGENTS.md non-negotiable #6.
212	    let missing_src_dirs: Vec<&Utf8PathBuf> =
213	        options.src_dirs.iter().filter(|dir| !dir.as_std_path().is_dir()).collect();
214	    if options.src_dirs.is_empty() {
215	        diagnostics.push(Diagnostic {
216	            severity: DiagnosticSeverity::Error,
217	            message: "No source directories configured — src_dirs is empty".into(),
218	            file: None,
219	            line: None,
220	            column: None,
221	            help: Some("Set --src (or docgen.config.ts srcDirs) to at least one directory to scan.".into()),
222	            code: DiagnosticCode::IoError,
223	        });
224	    } else if missing_src_dirs.len() == options.src_dirs.len() {
225	        diagnostics.push(Diagnostic {
226	            severity: DiagnosticSeverity::Error,
227	            message: format!(
228	                "None of the configured source directories exist: {}",
229	                options.src_dirs.iter().map(|dir| dir.as_str()).collect::<Vec<_>>().join(", ")
230	            ),
231	            file: options.src_dirs.first().map(ToString::to_string),
232	            line: None,
233	            column: None,
234	            help: Some("Check --src (or docgen.config.ts srcDirs) for a typo'd or stale path.".into()),
235	            code: DiagnosticCode::IoError,
236	        });
237	    } else {
238	        for dir in missing_src_dirs {
239	            diagnostics.push(Diagnostic {
240	                severity: DiagnosticSeverity::Warning,
241	                message: format!("Source directory does not exist: {dir}"),
242	                file: Some(dir.to_string()),
243	                line: None,
244	                column: None,
245	                help: Some("Check --src (or docgen.config.ts srcDirs) for a typo'd or stale path.".into()),
246	                code: DiagnosticCode::IoError,
247	            });
248	        }
249	    }
250	
251	    // Load the DTS parse-result cache (silently empty if missing/stale).
252	    let cache = Arc::new(DtsCache::load_from_disk(options.cache_dir.as_deref()));
253	    let cache_ref = Arc::clone(&cache);
254	
255	    // Phase 1: Discover source files.
256	    let (src_files, mut discover_diagnostics) = discover_files(&options.src_dirs, &options.exclude_patterns);
257	    diagnostics.append(&mut discover_diagnostics);
258	    let files_parsed = src_files.len() as u32;
259	
260	    // Counter for cache hits (atomic so rayon closures can increment safely).
261	    let cache_hits = AtomicU32::new(0);
262	
263	    // Phase 2: Parallel parse with rayon — check DTS cache for .d.ts files.
264	    // The whole closure body is wrapped in `contain_panic` so one file's
265	    // parse panicking (a bug in the OXC visitor, an unanticipated AST shape)
266	    // degrades to a per-file diagnostic instead of poisoning the entire
267	    // `.collect()` and crashing the whole extraction run for every file.
268	    let source_data_vec: Vec<(Utf8PathBuf, SourceData, Option<Diagnostic>)> = src_files
269	        .par_iter()
270	        .map(|path| {
271	            let label = format!("parse:{path}");
272	            crate::panic_guard::contain_panic(&label, || {
273	                #[cfg(test)]
274	                if path.file_name() == Some(PARSE_PANIC_TEST_SENTINEL) {
275	                    panic!("simulated parse-phase panic (test-only sentinel)");
276	                }
277	
278	                let is_dts = path.as_str().ends_with(".d.ts");
279	                let (source, io_diag) = match std::fs::read_to_string(path) {
280	                    Ok(s) => (s, None),
281	                    Err(e) => (String::new(), Some(Diagnostic::io_read_error(path, &e))),
282	                };
283	                // The cache key is a content hash (see cache.rs's CacheKey doc
284	                // comment for why, vs. mtime+size), so the file must already be
285	                // read before a cache lookup can happen — this is still exactly
286	                // one read either way (hit or miss), never two.
287	                if is_dts {
288	                    if let Some(cached) = cache_ref.get(path, &source) {
289	                        cache_hits.fetch_add(1, Ordering::Relaxed);
290	                        return (path.clone(), cached, io_diag);
291	                    }
292	                }
293	                let data = crate::extractor::parse_file(path, &source);
294	                if is_dts {
295	                    cache_ref.insert(path, &source, data.clone());
296	                }
297	                (path.clone(), data, io_diag)
298	            })
299	            .unwrap_or_else(|diag| (path.clone(), SourceData::default(), Some(diag)))
300	        })
301	        .collect();
302	
303	    let dts_cache_hits = cache_hits.load(Ordering::Relaxed);
304	
305	    // Phase 3: Merge into GlobalSourceData (sequential — fast hash-map insertions).
306	    let mut global = GlobalSourceData::default();
307	    let mut per_file_data = Vec::new();
308	    for (path, mut data, io_diag) in source_data_vec {
309	        if let Some(d) = io_diag {
310	            diagnostics.push(d);
311	        }
312	        // Surface any diagnostics the extractor raised while parsing this file
313	        // (excessive nesting, syntax errors) — never drop them silently.
314	        diagnostics.append(&mut data.diagnostics);
315	        diagnostics.extend(options.plugins.run_on_file_extracted(&path, &mut data));
316	        if capture_source_data {
317	            per_file_data.push((path.clone(), data.clone()));
318	        }
319	        global.merge(&path, data);
320	    }
321	
322	    // Phase 3.5: Full HTML attribute mode needs @types/react's real interfaces
323	    // (HTMLAttributes, AriaAttributes, ButtonHTMLAttributes, etc.) merged in
324	    // before resolution runs, so the resolver can look them up like any other
325	    // interface instead of just recording an InheritedLayer. Cached the same way
326	    // as any other .d.ts — this cost is paid once per @types/react version, not
327	    // per extraction run.
328	    if options.html_attributes == HtmlAttributeMode::Full {
329	        let from_dir = canonicalize_first_src_dir(&options.src_dirs).unwrap_or_else(|| Utf8PathBuf::from("."));
330	        match crate::resolver::resolve_package_dts_path(&from_dir, "react") {
331	            Some(react_dts_path) => {
332	                let react_dts_path = Utf8PathBuf::from(react_dts_path);
333	                merge_cached_dts_file(&react_dts_path, &cache, &mut global, &mut diagnostics);
334	            }
335	            None => {
336	                diagnostics.push(Diagnostic {
337	                    severity: DiagnosticSeverity::Warning,
338	                    message: "HtmlAttributeMode::Full requested but @types/react could not be resolved".into(),
339	                    file: None,
340	                    line: None,
341	                    column: None,
342	                    help: Some("Check that @types/react is installed. Falling back to curated attributes.".into()),
343	                    code: DiagnosticCode::MissingTypeLibrary,
344	                });
345	            }
346	        }
347	    }
348	
