  1	//! Evidence that a function renders, so a typed PascalCase function is a component and not a helper that happens to
  2	//! take an object. A typed first parameter alone admits `FormatName = (u: User) => string`, `debounce((q: Row) => …)`
  3	//! and selectors, so every rule that infers a component from a function asks this first.
  4	
  5	use oxc_ast::ast::*;
  6	use oxc_ast_visit::{walk, Visit};
  7	use oxc_syntax::scope::ScopeFlags;
  8	
  9	/// Why a function was judged not to render. Carried into the skip diagnostic.
 10	pub(super) type NoRender = &'static str;
 11	
 12	/// Names whose type, as a return annotation, means the function renders.
 13	const ELEMENT_TYPE_NAMES: &[&str] = &["Element", "ReactElement", "ReactNode", "ReactPortal", "JSX"];
 14	
 15	/// Callees that produce an element.
 16	const ELEMENT_FACTORIES: &[&str] = &["createElement", "cloneElement", "jsx", "jsxs", "jsxDEV"];
 17	
 18	fn rightmost_name<'n>(name: &'n TSTypeName<'_>) -> Option<&'n str> {
 19	    match name {
 20	        TSTypeName::IdentifierReference(id) => Some(id.name.as_str()),
 21	        TSTypeName::QualifiedName(q) => Some(q.right.name.as_str()),
 22	        _ => None,
 23	    }
 24	}
 25	
 26	/// Whether a return type annotation names a renderable result: `JSX.Element`, `ReactNode`, `ReactElement`, a union
 27	/// containing one, or `Promise` of one (async server components).
 28	pub(super) fn type_renders(ty: &TSType<'_>) -> bool {
 29	    match ty {
 30	        TSType::TSTypeReference(r) => {
 31	            let Some(name) = rightmost_name(&r.type_name) else { return false };
 32	            if name == "Promise" {
 33	                return r.type_arguments.as_ref().and_then(|a| a.params.first()).is_some_and(type_renders);
 34	            }
 35	            ELEMENT_TYPE_NAMES.contains(&name)
 36	        }
 37	        TSType::TSUnionType(u) => u.types.iter().any(type_renders),
 38	        TSType::TSParenthesizedType(p) => type_renders(&p.type_annotation),
 39	        _ => false,
 40	    }
 41	}
 42	
 43	/// Looks for JSX, an element factory call, a top-level hook call (only components and hooks may call hooks, and a
 44	/// PascalCase function is not a hook), or a top-level `return` of `null`, `children` or a call to a PascalCase function
 45	/// (a component invoked directly, `return JoinList({...})`). Nested functions still count for JSX (a render callback),
 46	/// but not for the top-level checks.
 47	#[derive(Default)]
 48	struct RenderFinder {
 49	    renders: bool,
 50	    nested: u32,
 51	}
 52	
 53	fn is_children(expr: &Expression<'_>) -> bool {
 54	    match expr {
 55	        Expression::Identifier(id) => id.name == "children",
 56	        Expression::StaticMemberExpression(m) => m.property.name == "children",
 57	        Expression::ParenthesizedExpression(p) => is_children(&p.expression),
 58	        _ => false,
 59	    }
 60	}
 61	
 62	fn callee_name<'n>(callee: &'n Expression<'_>) -> Option<&'n str> {
 63	    match callee {
 64	        Expression::Identifier(id) => Some(id.name.as_str()),
 65	        Expression::StaticMemberExpression(m) => Some(m.property.name.as_str()),
 66	        _ => None,
 67	    }
 68	}
 69	
 70	fn is_hook_name(name: &str) -> bool {
 71	    name.strip_prefix("use").is_some_and(|rest| rest.starts_with(|c: char| c.is_ascii_uppercase()))
 72	}
 73	
 74	fn returns_element_like(expr: &Expression<'_>) -> bool {
 75	    match expr {
 76	        Expression::NullLiteral(_) => true,
 77	        Expression::CallExpression(call) => callee_name(&call.callee)
 78	            .is_some_and(|n| n.starts_with(|c: char| c.is_ascii_uppercase()) || is_hook_name(n)),
 79	        Expression::ParenthesizedExpression(p) => returns_element_like(&p.expression),
 80	        _ => is_children(expr),
 81	    }
 82	}
 83	
 84	impl<'a> Visit<'a> for RenderFinder {
 85	    fn visit_jsx_element(&mut self, _it: &JSXElement<'a>) {
 86	        self.renders = true;
 87	    }
 88	
 89	    fn visit_jsx_fragment(&mut self, _it: &JSXFragment<'a>) {
 90	        self.renders = true;
 91	    }
 92	
 93	    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
 94	        let callee = callee_name(&it.callee);
 95	        if callee.is_some_and(|c| ELEMENT_FACTORIES.contains(&c) || (self.nested == 0 && is_hook_name(c))) {
 96	            self.renders = true;
 97	        }
 98	        walk::walk_call_expression(self, it);
 99	    }
100	
101	    fn visit_return_statement(&mut self, it: &ReturnStatement<'a>) {
102	        if self.nested == 0 && it.argument.as_ref().is_some_and(returns_element_like) {
103	            self.renders = true;
104	        }
105	        walk::walk_return_statement(self, it);
106	    }
107	
108	    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
109	        self.nested += 1;
110	        walk::walk_function(self, it, flags);
111	        self.nested -= 1;
112	    }
113	
114	    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
115	        self.nested += 1;
116	        walk::walk_arrow_function_expression(self, it);
117	        self.nested -= 1;
118	    }
119	}
120	
121	/// A function body: a block, or an arrow's single expression or block.
122	pub(super) enum Body<'b, 'a> {
123	    Block(&'b FunctionBody<'a>),
124	    Arrow(&'b ArrowFunctionBody<'a>),
125	}
126	
127	/// The parts of a function that decide whether it renders.
128	pub(super) struct FunctionShape<'b, 'a> {
129	    pub generator: bool,
130	    pub return_type: Option<&'b TSTypeAnnotation<'a>>,
131	    pub body: Option<Body<'b, 'a>>,
132	}
133	
134	impl<'b, 'a> FunctionShape<'b, 'a> {
135	    pub(super) fn of_arrow(f: &'b ArrowFunctionExpression<'a>) -> Self {
136	        Self { generator: false, return_type: f.return_type.as_deref(), body: Some(Body::Arrow(&f.body)) }
137	    }
138	
139	    pub(super) fn of_function(f: &'b Function<'a>) -> Self {
140	        Self { generator: f.generator, return_type: f.return_type.as_deref(), body: f.body.as_deref().map(Body::Block) }
141	    }
142	}
143	
144	/// `Ok` when the function renders; `Err` with the reason it does not.
145	pub(super) fn renders(shape: &FunctionShape<'_, '_>) -> Result<(), NoRender> {
146	    if shape.generator {
147	        return Err("is a generator");
148	    }
149	    if let Some(annotation) = shape.return_type {
150	        return if type_renders(&annotation.type_annotation) {
151	            Ok(())
152	        } else {
153	            Err("declares a return type that is not an element")
154	        };
155	    }
156	    let mut finder = RenderFinder::default();
157	    match &shape.body {
158	        None => return Err("has no body and no element return type"),
159	        Some(Body::Block(body)) => finder.visit_function_body(body),
160	        Some(Body::Arrow(body)) => {
161	            if let Some(expr) = body.as_expression() {
162	                if returns_element_like(expr) {
163	                    return Ok(());
164	                }
165	            }
166	            finder.visit_arrow_function_body(body);
167	        }
168	    }
169	    if finder.renders {
170	        Ok(())
171	    } else {
172	        Err("never renders: no JSX, element, hook call, or returned null, children or component call")
173	    }
174	}

  1	//! Components declared through a wrapper call whose props travel as a type argument:
  2	//! `const Button = polymorphicFactory<ButtonFactory>(...)`, `const Item = withContext<HTMLDivElement, ItemProps>(...)`.
  3	//!
  4	//! Nothing here names a library. A candidate is a PascalCase binding initialized with a generic call whose first
  5	//! argument could plausibly be a component (a function, a tag name, another component). The props type is chosen from
  6	//! the type arguments by shape, and only against declarations visible in the same file, so the rule needs no
  7	//! cross-file state. Candidates are resolved when the file finishes, because `type ButtonFactory = ...` is often
  8	//! declared after the call that uses it.
  9	
 10	use std::collections::BTreeMap;
 11	
 12	use oxc_ast::ast::*;
 13	use oxc_span::Span;
 14	
 15	use crate::types::{CollectedType, CollectedTypeAlias, ComponentMapping, DetectionRule, DiagnosticCode, TypeName};
 16	
 17	use super::evidence::{renders, FunctionShape};
 18	use super::SourceDataCollector;
 19	
 20	/// One type argument of a candidate wrapper call.
 21	pub(crate) struct WrapperTypeArg {
 22	    /// The reference name and its stringified type arguments, when the argument is a plain type reference.
 23	    reference: Option<(TypeName, Vec<CollectedType>)>,
 24	}
 25	
 26	/// A wrapper call waiting for the rest of the file to be seen.
 27	pub(crate) struct PendingWrapper {
 28	    name: String,
 29	    /// The only evidence was a tag name, so the props must come from a factory payload.
 30	    needs_payload: bool,
 31	    type_args: Vec<WrapperTypeArg>,
 32	    description: String,
 33	    tags: BTreeMap<String, String>,
 34	    span: Span,
 35	}
 36	
 37	/// Member that carries the props type inside a factory payload: `Factory<{ props: ButtonProps; ... }>`.
 38	const PAYLOAD_PROPS_MEMBER: &str = "props";
 39	
 40	/// Names that are DOM elements or refs rather than props, so they are never the props argument.
 41	fn is_element_type(name: &str) -> bool {
 42	    let bare = name.rsplit('.').next().unwrap_or(name);
 43	    bare == "Element" || ((bare.starts_with("HTML") || bare.starts_with("SVG")) && bare.ends_with("Element"))
 44	}
 45	
 46	fn is_element_type_arg(ty: &TSType<'_>) -> bool {
 47	    match ty {
 48	        TSType::TSTypeReference(r) => match &r.type_name {
 49	            TSTypeName::IdentifierReference(id) => is_element_type(id.name.as_str()),
 50	            TSTypeName::QualifiedName(q) => is_element_type(q.right.name.as_str()),
 51	            _ => false,
 52	        },
 53	        _ => false,
 54	    }
 55	}
 56	
 57	fn is_component_reference(name: &str) -> bool {
 58	    // `_Box` is Mantine's spelling of an implementation component.
 59	    name.trim_start_matches(['_', '$']).starts_with(|c: char| c.is_ascii_uppercase())
 60	}
 61	
 62	/// How strongly the first argument says the call builds a component.
 63	enum ArgumentEvidence {
 64	    Sufficient,
 65	    /// A tag name with no element type argument: a component only if a type argument is a factory payload.
 66	    TagNeedsPayload,
 67	}
 68	
 69	/// Evidence that the call builds a component from its first argument: a function that renders (Mantine's
 70	/// `factory<F>((props) => <Box />)`), a tag name next to an element type argument (`withContext<HTMLDivElement, P>("div")`)
 71	/// or a factory payload (`tableElement<TableTrFactory>("tr")`), a reference to a component
 72	/// (`withRootProvider<P>(Ark.Root)`), or a wrapped component (`polymorphic<P>(forwardRef(...))`). A tag string alone
 73	/// also describes `makeLabel<P>("button")`, and a lowercase value describes a context default or a store, so neither
 74	/// counts.
 75	fn component_argument_evidence(callee: &str, call: &CallExpression<'_>) -> Result<ArgumentEvidence, &'static str> {
 76	    if callee.rsplit('.').next() == Some("createContext") {
 77	        return Err("creates a context");
 78	    }
 79	    let Some(first) = call.arguments.first().and_then(Argument::as_expression) else {
 80	        return Err("has no argument that could be a component");
 81	    };
 82	    let element_type_arg = || call.type_arguments.as_ref().is_some_and(|a| a.params.iter().any(is_element_type_arg));
 83	    let sufficient = |r: Result<(), &'static str>| r.map(|()| ArgumentEvidence::Sufficient);
 84	    match first {
 85	        Expression::ArrowFunctionExpression(f) => {
 86	            sufficient(renders(&FunctionShape::of_arrow(f)).map_err(|_why| "is given a function that never renders"))
 87	        }
 88	        Expression::FunctionExpression(f) => {
 89	            sufficient(renders(&FunctionShape::of_function(f)).map_err(|_why| "is given a function that never renders"))
 90	        }
 91	        Expression::StringLiteral(_) if element_type_arg() => Ok(ArgumentEvidence::Sufficient),
 92	        Expression::StringLiteral(_) => Ok(ArgumentEvidence::TagNeedsPayload),
 93	        Expression::Identifier(id) if is_component_reference(id.name.as_str()) => Ok(ArgumentEvidence::Sufficient),
 94	        Expression::StaticMemberExpression(m) if is_component_reference(m.property.name.as_str()) => {
 95	            Ok(ArgumentEvidence::Sufficient)
 96	        }
 97	        Expression::CallExpression(inner) if super::component::is_component_wrapper_call(inner) => {
 98	            Ok(ArgumentEvidence::Sufficient)
 99	        }
100	        _ => Err("is given an argument that is not a render function, a tag or a component reference"),
101	    }
102	}
