104	impl<'src> SourceDataCollector<'src> {
105	    /// Record `const Name = callee<...>(first, ...)` as a candidate. Returns whether it was recorded.
106	    pub(super) fn try_record_wrapper_call<'a>(&mut self, decl: &super::component::Binding<'_, 'a>, name: &str) -> bool {
107	        let Some(init) = decl.init else { return false };
108	        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
109	        let Some(type_arguments) = call.type_arguments.as_ref() else { return false };
110	        let Some(callee) = self.extract_callee_name(call) else { return false };
111	        let needs_payload = match component_argument_evidence(&callee, call) {
112	            Ok(ArgumentEvidence::Sufficient) => false,
113	            Ok(ArgumentEvidence::TagNeedsPayload) => true,
114	            Err(reason) => {
115	                self.decline_reason = Some(format!("'{name}' is a generic call to '{callee}' that {reason}"));
116	                return false;
117	            }
118	        };
119	        let type_args: Vec<WrapperTypeArg> = type_arguments
120	            .params
121	            .iter()
122	            .map(|ty| WrapperTypeArg { reference: self.extract_type_name_from_type(ty) })
123	            .collect();
124	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
125	        self.pending_wrappers.push(PendingWrapper {
126	            name: name.to_owned(),
127	            needs_payload,
128	            type_args,
129	            description,
130	            tags,
131	            span: decl.span,
132	        });
133	        true
134	    }
135	
136	    /// Turn the recorded candidates into mappings, now that every declaration in the file is known.
137	    pub(super) fn promote_wrapper_calls(&mut self) {
138	        for pending in std::mem::take(&mut self.pending_wrappers) {
139	            if self.data.component_mappings.iter().any(|m| m.component_name == pending.name) {
140	                continue;
141	            }
142	            let selected = self
143	                .select_wrapper_props(&pending.type_args)
144	                .filter(|(_, _, from_payload)| *from_payload || !pending.needs_payload);
145	            let Some((props_name, props_args, _)) = selected else {
146	                self.record_skip(
147	                    DiagnosticCode::SkippedCandidate,
148	                    format!(
149	                        "'{}' looks like a component built by a wrapper call, but none of its type arguments names {}",
150	                        pending.name,
151	                        if pending.needs_payload {
152	                            "a factory payload, which a tag-name argument needs"
153	                        } else {
154	                            "a props type declared in this file or ending in Props"
155	                        }
156	                    ),
157	                    pending.span,
158	                );
159	                continue;
160	            };
161	            self.data.component_mappings.push(
162	                ComponentMapping::new(
163	                    pending.name,
164	                    props_name,
165	                    self.file_path.clone(),
166	                    pending.span.start,
167	                    pending.span.end,
168	                    DetectionRule::WrapperTypeArgument,
169	                )
170	                .with_props_type_args(props_args)
171	                .with_doc(pending.description, pending.tags),
172	            );
173	        }
174	    }
175	
176	    /// Pick the props type from a wrapper call's type arguments, last first (the props usually follow the element).
177	    /// The third field says whether the props came from a factory payload.
178	    fn select_wrapper_props(&self, type_args: &[WrapperTypeArg]) -> Option<(TypeName, Vec<CollectedType>, bool)> {
179	        for arg in type_args.iter().rev() {
180	            let Some((name, args)) = &arg.reference else { continue };
181	            if is_element_type(name) {
182	                continue;
183	            }
184	            if let Some(props) = self.payload_props(name) {
185	                return Some((props, Vec::new(), true));
186	            }
187	            let declared_here = self.data.interfaces.contains_key(&self.scoped_key(name))
188	                || self.data.type_aliases.contains_key(&self.scoped_key(name));
189	            // A name from another file cannot be inspected here; only the props naming convention vouches for it.
190	            if declared_here || name.ends_with("Props") {
191	                return Some((name.clone(), args.clone(), false));
192	            }
193	        }
194	        None
195	    }
196	
197	    /// `type ButtonFactory = Anything<{ props: ButtonProps; ... }>` yields `ButtonProps`.
198	    fn payload_props(&self, alias_name: &str) -> Option<TypeName> {
199	        let CollectedTypeAlias::Passthrough { target: CollectedType::Named { args, .. }, .. } =
200	            self.data.type_aliases.get(&self.scoped_key(alias_name))?
201	        else {
202	            return None;
203	        };
204	        args.iter().find_map(|arg| match arg {
205	            CollectedType::Object(fields) => fields.iter().find_map(|field| match &field.collected_type {
206	                CollectedType::Named { name, args } if field.name == PAYLOAD_PROPS_MEMBER && args.is_empty() => {
207	                    Some(name.clone())
208	                }
209	                _ => None,
210	            }),
211	            _ => None,
212	        })
213	    }
214	}

