  1	//! Shared "try the project's own source before falling back to known
  2	//! library-pattern shortcuts" resolution order.
  3	//!
  4	//! `named.rs` documented this order as intentional (source-defined types
  5	//! like `ThemingProps`/`StylesApiProps` must never be silently replaced by
  6	//! an opaque known-pattern shortcut). `chain.rs`'s `extends`-clause path
  7	//! independently reimplemented the same sequence and got it backwards —
  8	//! checking known patterns first. This is now the *only* place either call
  9	//! site may implement that order, so they can't drift apart again.
 10	
 11	use camino::{Utf8Path, Utf8PathBuf};
 12	
 13	use crate::known::{resolve_known, KnownPatternResult};
 14	use crate::types::*;
 15	
 16	use super::import::{lookup_interface, lookup_type_alias, resolve_to_canonical};
 17	use super::ResolutionContext;
 18	
 19	/// What `resolve_source_defined_or_known` found, in the order it checked.
 20	pub(super) enum SourceOrKnownMatch<'g> {
 21	    /// A type alias declared in the project's own source (or an already-merged
 22	    /// ambient/library `.d.ts`). `matched_key` is the exact key it was found
 23	    /// under (bare or `React.`-qualified) — callers need it to also look up
 24	    /// `type_alias_params` under the same key.
 25	    TypeAlias { matched_key: String, alias: CollectedTypeAlias },
 26	    /// An interface declared in the project's own source. `named.rs` only
 27	    /// needs to know a match occurred (it returns a bare `Named` either way);
 28	    /// `chain.rs`'s wiring reads the interface itself to expand its props.
 29	    Interface(&'g CollectedInterface),
 30	    /// No source declaration found — a recognized library pattern instead.
 31	    Known(KnownPatternResult),
 32	}
 33	
 34	/// Resolve `name` to canonical `(file, name)`, then try — in this fixed
 35	/// order — a type alias, an interface, and only then a known-pattern
 36	/// shortcut. Returns the canonical `(file, name)` pair (callers need it
 37	/// regardless of outcome, e.g. for an "unresolvable" diagnostic when nothing
 38	/// matched) alongside whichever of the three matched, if any.
 39	pub(super) fn resolve_source_defined_or_known<'g>(
 40	    name: &str,
 41	    resolved_args: &[PropType],
 42	    consuming_file: &Utf8Path,
 43	    ctx: &'g ResolutionContext,
 44	    state: &mut ResolveState,
 45	) -> (Utf8PathBuf, String, Option<SourceOrKnownMatch<'g>>) {
 46	    super::deps::record(consuming_file);
 47	    let (canonical_file, canonical_name) = resolve_to_canonical(name, consuming_file, ctx, &mut state.diagnostics)
 48	        .unwrap_or_else(|| (consuming_file.to_owned(), name.to_owned()));
 49	
 50	    if let Some((matched_key, alias)) = lookup_type_alias(ctx, canonical_file.as_str(), &canonical_name) {
 51	        return (
 52	            canonical_file,
 53	            canonical_name,
 54	            Some(SourceOrKnownMatch::TypeAlias { matched_key: matched_key.to_string(), alias: alias.clone() }),
 55	        );
 56	    }
 57	
 58	    if let Some(iface) = lookup_interface(ctx, canonical_file.as_str(), &canonical_name) {
 59	        return (canonical_file, canonical_name, Some(SourceOrKnownMatch::Interface(iface)));
 60	    }
 61	
 62	    if let Some(result) = resolve_known(name, resolved_args, &ctx.global, &ctx.enum_bare_index) {
 63	        return (canonical_file, canonical_name, Some(SourceOrKnownMatch::Known(result)));
 64	    }
 65	
 66	    (canonical_file, canonical_name, None)
 67	}
