 1	//! What a component's resolution depended on, so watch mode re-resolves exactly the components an edit can change. A
 2	//! component resolves on one thread from start to finish, so the recorder is thread-local and scoped to one
 3	//! `resolve_component` call; lookups record into it without every resolver function threading a collector through.
 4	
 5	use std::cell::RefCell;
 6	
 7	use camino::Utf8Path;
 8	use compact_str::CompactString;
 9	use rustc_hash::FxHashSet;
10	
11	use crate::path_key::PathKey;
12	
13	/// Everything outside the component's own mapping that its resolution read.
14	#[derive(Clone, Debug, Default, PartialEq, Eq)]
15	pub(crate) struct Dependencies {
16	    /// Source files whose declarations, imports or exports were read, including lookups that found nothing there.
17	    pub(crate) files: FxHashSet<PathKey>,
18	    /// Enum and const-array names looked up project-wide by bare name. A file that starts or stops declaring one of
19	    /// these can change which declaration the name binds to.
20	    pub(crate) bare_names: FxHashSet<CompactString>,
21	    /// Whether a module specifier was resolved. A new file can change what a specifier resolves to (or make an
22	    /// unresolvable one resolve); an edit or deletion cannot, beyond the resolved file already in `files`.
23	    pub(crate) resolves_modules: bool,
24	}
25	
26	thread_local! {
27	    static RECORDER: RefCell<Option<Dependencies>> = const { RefCell::new(None) };
28	}
29	
30	fn with_recorder(f: impl FnOnce(&mut Dependencies)) {
31	    RECORDER.with(|recorder| {
32	        if let Some(deps) = recorder.borrow_mut().as_mut() {
33	            f(deps);
34	        }
35	    });
36	}
37	
38	/// Note that the current resolution read `file`. A no-op outside `recording`.
39	pub(super) fn record(file: &Utf8Path) {
40	    with_recorder(|deps| {
41	        if !deps.files.contains(file.as_str()) {
42	            deps.files.insert(PathKey::from(file));
43	        }
44	    });
45	}
46	
47	/// Note a project-wide lookup of an enum or const array by bare name.
48	pub(super) fn record_bare_name(name: &str) {
49	    with_recorder(|deps| {
50	        if !deps.bare_names.contains(name) {
51	            deps.bare_names.insert(CompactString::from(name));
52	        }
53	    });
54	}
55	
56	/// Note that a module specifier was resolved.
57	pub(super) fn record_module_resolution() {
58	    with_recorder(|deps| deps.resolves_modules = true);
59	}
60	
61	/// Run `f` and return what it depended on. Not reentrant: resolution never nests a component inside another.
62	pub(super) fn recording<T>(f: impl FnOnce() -> T) -> (T, Dependencies) {
63	    RECORDER.with(|recorder| *recorder.borrow_mut() = Some(Dependencies::default()));
64	    let result = f();
65	    let deps = RECORDER.with(|recorder| recorder.borrow_mut().take()).unwrap_or_default();
66	    (result, deps)
67	}

