 12	/// Canonicalize `path`, falling back to canonicalizing its parent directory
 13	/// and rejoining the file name when the full path can't be resolved (e.g. the
 14	/// file doesn't exist yet — created and then immediately edited before this
 15	/// session ever saw it read successfully). Falls back to `path` unchanged only
 16	/// when even the parent doesn't exist. Deliberately stable across a file's
 17	/// create/delete transitions: the parent directory is what actually needs a
 18	/// consistent identity across repeated `update_file` calls for the same file,
 19	/// not the file itself.
 20	fn canonicalize_best_effort(path: &Utf8Path) -> Utf8PathBuf {
 21	    if let Ok(p) = std::fs::canonicalize(path.as_std_path()) {
 22	        if let Ok(p) = Utf8PathBuf::from_path_buf(p) {
 23	            return p;
 24	        }
 25	    }
 26	    if let (Some(parent), Some(file_name)) = (path.parent(), path.file_name()) {
 27	        if let Ok(p) = std::fs::canonicalize(parent.as_std_path()) {
 28	            if let Ok(mut p) = Utf8PathBuf::from_path_buf(p) {
 29	                p.push(file_name);
 30	                return p;
 31	            }
 32	        }
 33	    }
 34	    path.to_owned()
 35	}
