 37	/// Stateful session for incremental watch-mode extraction.
 38	///
 39	/// The session holds one immutable `Revision` at a time. `update_file` builds the next revision from the current one
 40	/// (re-parsing the changed file, re-resolving the components whose resolution read it) and publishes it with a single
 41	/// atomic store, so a reader always sees one complete revision, never parts of two. Writers are serialized; readers
 42	/// never wait on them.
 43	pub struct WatchSession {
 44	    pub options: PipelineOptions,
 45	    current: ArcSwapOption<Revision>,
 46	    writer: Mutex<()>,
 47	}
 48	
 49	impl WatchSession {
 50	    /// Create an empty WatchSession (call `initialize()` before first use).
 51	    pub fn new(options: PipelineOptions) -> Self {
 52	        Self { options, current: ArcSwapOption::empty(), writer: Mutex::new(()) }
 53	    }
 54	
 55	    /// Run a full cold extraction to populate this session.
 56	    ///
 57	    /// Idempotent — concurrent or repeated calls return the current snapshot without re-running extraction. Use
 58	    /// `rebuild` to force a fresh extraction.
 59	    pub fn initialize(&self) -> ExtractionOutput {
 60	        let _writer = self.writer.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
 61	        if let Some(current) = self.current.load_full() {
 62	            return (*current.output).clone();
 63	        }
 64	        let revision = Arc::new(Revision::cold(&self.options, 1));
 65	        let output = (*revision.output).clone();
 66	        self.current.store(Some(revision));
 67	        output
 68	    }
 69	
 70	    /// Discard the session's state and extract everything again.
 71	    pub fn rebuild(&self) -> ExtractionOutput {
 72	        let _writer = self.writer.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
 73	        let id = self.current.load().as_ref().map_or(1, |r| r.id + 1);
 74	        let revision = Arc::new(Revision::cold(&self.options, id));
 75	        let output = (*revision.output).clone();
 76	        self.current.store(Some(revision));
 77	        output
 78	    }
 79	
 80	    /// The published revision's number: 0 before `initialize`, then one higher for every change that produced a new
 81	    /// revision. An update that leaves it unchanged changed nothing.
 82	    pub fn revision(&self) -> u64 {
 83	        self.current.load().as_ref().map_or(0, |revision| revision.id)
 84	    }
 85	
 86	    /// The current output: exactly what a cold `extract()` of the same files would return. Empty before `initialize`.
 87	    pub fn snapshot(&self) -> ExtractionOutput {
 88	        match self.current.load_full() {
 89	            Some(revision) => (*revision.output).clone(),
 90	            None => ExtractionOutput {
 91	                components: BTreeMap::new(),
 92	                enums: BTreeMap::new(),
 93	                diagnostics: Vec::new(),
 94	                stats: ExtractionStats::default(),
