 99	    /// Apply one file change: an edit, a new file, or a deletion. A path that is not a source file of this project
100	    /// (outside every source directory, excluded, or not TypeScript) changes nothing.
101	    pub fn update_file(&self, changed: &Utf8Path) -> IncrementalUpdate {
102	        // `discover_files` canonicalizes the paths it reports (e.g. macOS's `/var` -> `/private/var`), so a watcher's
103	        // path must be canonicalized the same way to match.
104	        let changed = canonicalize_best_effort(changed);
105	        let _writer = self.writer.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
106	        let current = match self.current.load_full() {
107	            Some(current) => current,
108	            None => {
109	                let revision = Arc::new(Revision::cold(&self.options, 1));
110	                self.current.store(Some(revision.clone()));
111	                revision
112	            }
113	        };
114	        match current.next(&self.options, &changed) {
115	            Some((next, update)) => {
116	                self.current.store(Some(Arc::new(next)));
117	                update
118	            }
119	            None => IncrementalUpdate {
120	                revision: current.id,
121	                updated_components: Vec::new(),
122	                updated_keys: Vec::new(),
123	                removed_keys: Vec::new(),
124	                affected_files: Vec::new(),
125	                diagnostics: Vec::new(),
126	                duration_ms: 0,
127	            },
128	        }
129	    }
130	}
