 43	impl Resolved {
 44	    /// Whether this resolution can differ after `change`.
 45	    fn affected_by(&self, change: &Change<'_>) -> bool {
 46	        self.depends_on.files.contains(change.file.as_str())
 47	            || (change.created && self.depends_on.resolves_modules)
 48	            || change.bare_names.iter().any(|name| self.depends_on.bare_names.contains(name.as_str()))
 49	    }
 50	}
