 52	/// One file's change, as far as dependency tracking cares.
 53	struct Change<'c> {
 54	    file: &'c Utf8Path,
 55	    /// The file did not exist in the previous revision.
 56	    created: bool,
 57	    /// Enum and const-array names the file declared before or after the change.
 58	    bare_names: FxHashSet<String>,
 59	}
