 61	/// The bare names `file` declares in an enum or const-array map keyed `file:name`.
 62	fn bare_names_declared<V>(file: &Utf8Path, map: &FxHashMap<String, V>) -> Vec<String> {
 63	    let prefix = format!("{file}:");
 64	    map.keys().filter_map(|key| key.strip_prefix(prefix.as_str()).map(str::to_owned)).collect()
 65	}
