 67	pub(crate) struct Revision {
 68	    pub(crate) id: u64,
 69	    global: Arc<GlobalSourceData>,
 70	    named_types: Arc<NamedTypeIndex>,
 71	    ambient_global_files: Vec<Utf8PathBuf>,
 72	    /// Source-directory and discovery diagnostics.
 73	    head_diagnostics: Vec<Diagnostic>,
 74	    /// Read, parse and file-plugin diagnostics, per source file.
 75	    file_diagnostics: BTreeMap<Utf8PathBuf, Vec<Diagnostic>>,
 76	    /// `@types/react` and TypeScript lib diagnostics.
 77	    lib_diagnostics: Vec<Diagnostic>,
 78	    /// The parse-cache save result.
 79	    tail_diagnostics: Vec<Diagnostic>,
