 81	    /// The project's source files.
 82	    files: Arc<FxHashSet<Utf8PathBuf>>,
 83	    /// `.d.ts` files the cold run parsed or loaded from the parse cache, and how many the cache answered.
 84	    dts_files_parsed: u32,
 85	    dts_cache_hits: u32,
 86	    duration_ms: u64,
