 92	/// The mapping identities of `global`, in output order: by file, then by position in the file.
 93	fn component_ids<'g>(
 94	    global: &'g GlobalSourceData,
 95	    options: &PipelineOptions,
 96	) -> Vec<(ComponentId, &'g ComponentMapping)> {
 97	    let mut ordinals: FxHashMap<(&Utf8Path, &str), u32> = FxHashMap::default();
 98	    let mut ids: Vec<(ComponentId, &ComponentMapping)> = global
 99	        .component_mappings
100	        .iter()
101	        .filter(|m| !should_skip(&m.component_name, &options.exclude_prefixes))
102	        .map(|m| {
103	            let ordinal = ordinals.entry((m.file_path.as_path(), m.component_name.as_str())).or_insert(0);
104	            let id = ComponentId { file: m.file_path.clone(), name: m.component_name.clone(), ordinal: *ordinal };
105	            *ordinal += 1;
106	            (id, m)
107	        })
108	        .collect();
109	    ids.sort_by(|(a, ma), (b, mb)| (&a.file, ma.span_start, a.ordinal).cmp(&(&b.file, mb.span_start, b.ordinal)));
110	    ids
111	}
112	
113	fn resolve_all(
114	    mappings: &[(ComponentId, &ComponentMapping)],
115	    ctx: &ResolutionContext,
116	) -> FxHashMap<ComponentId, Arc<Resolved>> {
117	    let borrowed: Vec<&ComponentMapping> = mappings.iter().map(|(_, m)| *m).collect();
118	    resolve_guarded(&borrowed, ctx)
119	        .into_iter()
120	        .zip(mappings)
121	        .map(|((entry, diagnostics, depends_on), (id, _))| {
122	            (id.clone(), Arc::new(Resolved { entry, diagnostics, depends_on }))
123	        })
124	        .collect()
125	}
