127	impl Revision {
128	    /// Discover, parse, merge, resolve and assemble every source file.
129	    pub(crate) fn cold(options: &PipelineOptions, id: u64) -> Revision {
130	        let start = Instant::now();
131	        let mut head_diagnostics = source_dir_diagnostics(options);
132	
133	        let cache = Arc::new(DtsCache::load_from_disk(options.cache_dir.as_deref()));
134	        head_diagnostics.extend(cache.load_diagnostic().cloned());
135	
136	        let (src_files, discover_diagnostics) = discover_files(&options.src_dirs, &options.exclude_patterns);
137	        head_diagnostics.extend(discover_diagnostics);
138	
139	        // The whole closure body is wrapped in `contain_panic` so one file's parse panicking degrades to a per-file
140	        // diagnostic instead of poisoning the `.collect()` and crashing the whole extraction run.
141	        let parsed: Vec<(Utf8PathBuf, SourceData, Option<Diagnostic>)> = src_files
142	            .par_iter()
143	            .map(|path| {
144	                let label = format!("parse:{path}");
145	                crate::panic_guard::contain_panic(&label, || {
146	                    #[cfg(test)]
147	                    if path.file_name() == Some(super::PARSE_PANIC_TEST_SENTINEL) {
148	                        panic!("simulated parse-phase panic (test-only sentinel)");
149	                    }
150	                    let (data, io_diag) = parse_source_file(path, &cache);
151	                    (path.clone(), data, io_diag)
152	                })
153	                .unwrap_or_else(|diag| (path.clone(), SourceData::default(), Some(diag)))
154	            })
155	            .collect();
156	
157	        let mut global = GlobalSourceData::default();
158	        let mut file_diagnostics: BTreeMap<Utf8PathBuf, Vec<Diagnostic>> = BTreeMap::new();
159	        for (path, mut data, io_diag) in parsed {
160	            let mut diags: Vec<Diagnostic> = io_diag.into_iter().collect();
161	            diags.append(&mut data.diagnostics);
162	            diags.extend(options.plugins.run_on_file_extracted(&path, &mut data));
163	            if !diags.is_empty() {
164	                file_diagnostics.insert(path.clone(), diags);
165	            }
166	            global.merge(&path, data);
167	        }
168	
169	        let mut lib_diagnostics = Vec::new();
170	        // Full HTML attribute mode needs @types/react's real interfaces merged before resolution, so the resolver can
171	        // look them up like any other interface instead of only recording an InheritedLayer.
172	        if options.html_attributes == HtmlAttributeMode::Full {
173	            let from_dir = canonicalize_first_src_dir(&options.src_dirs).unwrap_or_else(|| Utf8PathBuf::from("."));
174	            match crate::resolver::resolve_package_dts_path(&from_dir, "react") {
175	                Some(react_dts_path) => {
176	                    let react_dts_path = Utf8PathBuf::from(react_dts_path);
177	                    merge_cached_dts_file(&react_dts_path, &cache, &mut global, &mut lib_diagnostics);
178	                }
179	                None => lib_diagnostics.push(
180	                    Diagnostic::new(
181	                        DiagnosticSeverity::Warning,
182	                        DiagnosticCode::MissingTypeLibrary,
183	                        "HtmlAttributeMode::Full requested but @types/react could not be resolved",
184	                    )
185	                    .with_help("Check that @types/react is installed. Falling back to curated attributes."),
186	                ),
187	            }
188	        }
189	        // Ambient globals (Date, Element, ...) live in TS's lib files and are never imported, so merge them in every
190	        // mode. An install missing a lib file (TS 7 without its platform package) is reported here.
191	        if let Some(from_dir) = canonicalize_first_src_dir(&options.src_dirs) {
192	            let libs = crate::resolver::resolve_ts_lib_paths(&from_dir);
193	            lib_diagnostics.extend(libs.diagnostic);
194	            for lib_path in libs.paths {
195	                merge_cached_dts_file(&Utf8PathBuf::from(lib_path), &cache, &mut global, &mut lib_diagnostics);
196	            }
197	        }
198	
199	        let global = Arc::new(global);
200	        let named_types = Arc::new(NamedTypeIndex::build(&global));
201	        let ambient_global_files = crate::resolver::compute_ambient_global_files(options);
202	        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
203	            global.clone(),
204	            options,
205	            ambient_global_files.clone(),
206	            named_types.clone(),
207	        );
208	        let resolved = resolve_all(&component_ids(&global, options), &ctx);
209	        let files = Arc::new(src_files.into_iter().collect());
210	
211	        let (dts_files_parsed, dts_cache_hits) = cache.counts();
212	        // Arc::try_unwrap succeeds because all rayon workers have finished.
213	        let tail_diagnostics: Vec<Diagnostic> = match Arc::try_unwrap(cache) {
214	            Ok(c) => c.save_to_disk(),
215	            Err(arc) => arc.save_to_disk(),
216	        }
217	        .into_iter()
218	        .collect();
219	
220	        let mut revision = Revision {
221	            id,
222	            global,
223	            named_types,
224	            ambient_global_files,
225	            head_diagnostics,
226	            file_diagnostics,
227	            lib_diagnostics,
228	            tail_diagnostics,
229	            resolved,
230	            files,
231	            dts_files_parsed,
232	            dts_cache_hits,
233	            duration_ms: 0,
234	            output: Arc::new(empty_output()),
235	            keys: FxHashMap::default(),
236	        };
237	        revision.duration_ms = start.elapsed().as_millis() as u64;
238	        revision.assemble(options);
239	        revision
240	    }
