242	    /// The revision after `changed` was edited, created or deleted, and the delta from this one. `None` when the path
243	    /// is not a source file of this project (outside every source directory, excluded, or not TypeScript).
244	    pub(crate) fn next(&self, options: &PipelineOptions, changed: &Utf8Path) -> Option<(Revision, IncrementalUpdate)> {
245	        if !is_source_file(changed, &options.src_dirs, &options.exclude_patterns) {
246	            return None;
247	        }
248	        let start = Instant::now();
249	
250	        let mut global = (*self.global).clone();
251	        let mut named_types = (*self.named_types).clone();
252	        let mut file_diagnostics = self.file_diagnostics.clone();
253	        let mut files = (*self.files).clone();
254	        let mut bare_names: FxHashSet<String> = bare_names_declared(changed, &self.global.enums).into_iter().collect();
255	        bare_names.extend(bare_names_declared(changed, &self.global.const_arrays));
256	        global.remove_file(changed);
257	        named_types.remove_file(changed);
258	        file_diagnostics.remove(changed);
259	
260	        let read = match std::fs::read_to_string(changed) {
261	            Ok(source) => Some((source, None)),
262	            // Deleted: its declarations and diagnostics leave with it.
263	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
264	            // Unreadable (permissions, invalid UTF-8): declares nothing, exactly as in a cold run.
265	            Err(e) => Some((String::new(), Some(Diagnostic::io_read_error(changed, &e)))),
266	        };
267	        let created = match read {
268	            None => {
269	                files.remove(changed);
270	                false
271	            }
272	            Some((source, io_diag)) => {
273	                let mut data = crate::extractor::parse_file(changed, &source);
274	                let mut diags: Vec<Diagnostic> = io_diag.into_iter().collect();
275	                diags.append(&mut data.diagnostics);
276	                diags.extend(options.plugins.run_on_file_extracted(changed, &mut data));
277	                if !diags.is_empty() {
278	                    file_diagnostics.insert(changed.to_owned(), diags);
279	                }
280	                bare_names.extend(bare_names_declared(changed, &data.enums));
281	                bare_names.extend(bare_names_declared(changed, &data.const_arrays));
282	                named_types.merge_file(&data);
283	                global.merge(changed, data);
284	                files.insert(changed.to_owned())
285	            }
286	        };
287	        let change = Change { file: changed, created, bare_names };
288	
289	        let global = Arc::new(global);
290	        let named_types = Arc::new(named_types);
291	        let ids = component_ids(&global, options);
292	        let (stale, kept): (Vec<_>, Vec<_>) = ids.into_iter().partition(|(id, _)| match self.resolved.get(id) {
293	            None => true,
294	            Some(previous) => id.file == changed || previous.affected_by(&change),
295	        });
296	        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
297	            global.clone(),
298	            options,
299	            self.ambient_global_files.clone(),
300	            named_types.clone(),
301	        );
302	        let fresh = resolve_all(&stale, &ctx);
303	        let mut resolved: FxHashMap<ComponentId, Arc<Resolved>> =
304	            kept.into_iter().filter_map(|(id, _)| self.resolved.get(&id).map(|r| (id, r.clone()))).collect();
305	        let fresh_ids: Vec<ComponentId> = fresh.keys().cloned().collect();
306	        resolved.extend(fresh);
307	
308	        let mut next = Revision {
309	            id: self.id + 1,
310	            global,
311	            named_types,
312	            ambient_global_files: self.ambient_global_files.clone(),
313	            head_diagnostics: self.head_diagnostics.clone(),
314	            file_diagnostics,
315	            lib_diagnostics: self.lib_diagnostics.clone(),
316	            tail_diagnostics: self.tail_diagnostics.clone(),
317	            resolved,
318	            files: Arc::new(files),
319	            dts_files_parsed: self.dts_files_parsed,
320	            dts_cache_hits: self.dts_cache_hits,
321	            duration_ms: self.duration_ms,
322	            output: Arc::new(empty_output()),
323	            keys: FxHashMap::default(),
324	        };
325	        next.assemble(options);
326	
327	        let updated_components: Vec<(String, ComponentEntry)> = fresh_ids
328	            .iter()
329	            .filter_map(|id| {
330	                Some((next.keys.get(id)?.clone(), next.output.components.get(next.keys.get(id)?)?.clone()))
331	            })
332	            .collect();
333	        let removed_keys: Vec<String> =
334	            self.output.components.keys().filter(|key| !next.output.components.contains_key(*key)).cloned().collect();
335	        let mut affected_files: Vec<Utf8PathBuf> = fresh_ids.iter().map(|id| id.file.clone()).collect();
336	        affected_files.sort();
337	        affected_files.dedup();
338	        // The changed file's own diagnostics and those of every re-resolved component.
339	        let updated: FxHashSet<&str> = updated_components.iter().map(|(key, _)| key.as_str()).collect();
340	        let diagnostics: Vec<Diagnostic> = next
341	            .output
342	            .diagnostics
343	            .iter()
344	            .filter(|d| {
345	                d.file.as_deref() == Some(changed.as_str())
346	                    || d.affects.iter().any(|key| updated.contains(key.as_str()))
347	            })
348	            .cloned()
349	            .collect();
350	        let update = IncrementalUpdate {
351	            revision: next.id,
352	            updated_components: updated_components.iter().map(|(_, entry)| entry.clone()).collect(),
353	            updated_keys: updated_components.into_iter().map(|(key, _)| key).collect(),
354	            removed_keys,
355	            affected_files,
356	            diagnostics,
357	            duration_ms: start.elapsed().as_millis() as u64,
358	        };
359	        Some((next, update))
360	    }
