362	    /// Build the public output from the revision: components keyed with the same disambiguation rule everywhere,
363	    /// plugin hooks applied, diagnostics in a stable order, public enums.
364	    fn assemble(&mut self, options: &PipelineOptions) {
365	        let mut diagnostics = DiagnosticSet::default();
366	        diagnostics.extend(self.head_diagnostics.iter().cloned(), None);
367	        for diags in self.file_diagnostics.values() {
368	            diagnostics.extend(diags.iter().cloned(), None);
369	        }
370	        diagnostics.extend(self.lib_diagnostics.iter().cloned(), None);
371	
372	        let mut components = BTreeMap::new();
373	        let mut keys = FxHashMap::default();
374	        let mut seen_names: FxHashMap<String, u32> = FxHashMap::default();
375	        for (id, _) in component_ids(&self.global, options) {
376	            let Some(resolved) = self.resolved.get(&id) else { continue };
377	            let mut entry = resolved.entry.clone();
378	            let base_name = entry.display_name.clone();
379	            let count = seen_names.entry(base_name.clone()).or_insert(0);
380	            *count += 1;
381	            // The first occurrence of a name keeps it bare; later ones take their file path, which is unique per file.
382	            let key = if *count == 1 { base_name } else { format!("{} ({})", base_name, entry.file_path) };
383	            diagnostics.extend(options.plugins.run_on_component_resolved(&mut entry), Some(&key));
384	            let new_file_path = entry.file_path.clone();
385	            if let Some(previous) = components.insert(key.clone(), entry) {
386	                diagnostics.add(
387	                    Diagnostic::new(
388	                        DiagnosticSeverity::Warning,
389	                        DiagnosticCode::ComponentKeyCollision,
390	                        format!(
391	                            "Duplicate component key '{key}' — colliding file paths: previously '{}', now '{}'",
392	                            previous.file_path, new_file_path
393	                        ),
394	                    )
395	                    .with_file(new_file_path.to_string())
396	                    .with_help(
397	                        "Two resolved components produced the same display name and disambiguation key — only the \
398	                         later one is kept in the output. Check for overlapping src_dirs or a genuine duplicate \
399	                         declaration.",
400	                    ),
401	                    None,
402	                );
403	            }
404	            diagnostics.extend(resolved.diagnostics.iter().cloned(), Some(&key));
405	            keys.insert(id, key);
406	        }
407	
408	        let (enums, enum_diagnostics) = collect_public_enums(&self.global);
409	        diagnostics.extend(enum_diagnostics, None);
410	        diagnostics.extend(self.tail_diagnostics.iter().cloned(), None);
411	
412	        let components_extracted = components.len() as u32;
413	        self.output = Arc::new(ExtractionOutput {
414	            components,
415	            enums,
416	            diagnostics: diagnostics.finish(),
417	            stats: ExtractionStats {
418	                components_extracted,
419	                files_parsed: self.files.len() as u32,
420	                dts_files_parsed: self.dts_files_parsed,
421	                dts_cache_hits: self.dts_cache_hits,
422	                duration_ms: self.duration_ms,
423	                ..Default::default()
424	            },
425	        });
426	        self.keys = keys;
427	    }
428	}
