478	/// Read and parse one source file, through the parse cache for `.d.ts`.
479	fn parse_source_file(path: &Utf8Path, cache: &DtsCache) -> (SourceData, Option<Diagnostic>) {
480	    let is_dts = path.as_str().ends_with(".d.ts");
481	    let (source, io_diag) = match std::fs::read_to_string(path) {
482	        Ok(s) => (s, None),
483	        Err(e) => (String::new(), Some(Diagnostic::io_read_error(path, &e))),
484	    };
485	    if is_dts {
486	        if let Some(cached) = cache.get(path, &source) {
487	            return (cached, io_diag);
488	        }
489	    }
490	    let data = crate::extractor::parse_file(path, &source);
491	    if is_dts {
