 19	/// Bump this whenever `SourceData`'s field list or field order changes.
 20	/// Serialization is via plain `rmp_serde::to_vec`/`from_slice` — MessagePack's
 21	/// *positional* (not named-map) struct encoding — so inserting a field
 22	/// anywhere but the very end shifts every subsequent field's decode position
 23	/// for any cache entry written before the change. A same-shaped field
 24	/// addition (e.g. another `FxHashMap<String, Vec<X>>`) wouldn't even fail
 25	/// loudly; it would decode as plausible-looking but wrong data. `const_arrays`
 26	/// (added mid-struct, not appended) is exactly this case — this bump covers it.
 27	/// Also bumped for the mtime+size -> content-hash key change (P0-2 fix):
 28	/// `SerializableCacheKey`'s own shape changed, so pre-existing on-disk cache
 29	/// files must be discarded rather than misread under the new field layout.
 30	/// Extractor changes that keep the shape are covered by `CacheHeader::fingerprint` instead.
 31	const CACHE_SCHEMA_VERSION: u32 = 13;
 32	
 33	const DATA_FILE: &str = "dts.msgpack";
