 35	/// Written first in the payload, so a cache written by a different build is recognized before its entries are decoded.
 36	/// The manifest repeats it for inspection only.
 37	#[derive(Serialize, Deserialize, PartialEq, Debug)]
 38	struct CacheHeader {
 39	    schema: u32,
 40	    version: String,
 41	    /// A hash of this crate's sources and locked dependencies (see `build.rs`): any change to the code that produces
 42	    /// `SourceData` invalidates the cache, bumped or not.
 43	    fingerprint: String,
 44	}
