 46	impl CacheHeader {
 47	    fn current() -> CacheHeader {
 48	        CacheHeader {
 49	            schema: CACHE_SCHEMA_VERSION,
 50	            version: env!("CARGO_PKG_VERSION").to_owned(),
 51	            fingerprint: env!("CALIPER_SOURCE_FINGERPRINT").to_owned(),
 52	        }
