 56	// ─── Internal key type ────────────────────────────────────────────────────────
 57	
 58	/// Keyed by a hash of the file's actual byte content, not `(size, mtime)`.
 59	///
 60	/// The prior mtime+size scheme had a documented staleness gap (P0-2): on
 61	/// filesystems/environments with coarse mtime resolution (network FS,
 62	/// container overlay FS, or simply two edits landing in the same clock
 63	/// tick), an edit completing within the same tick and producing a
 64	/// same-length file was indistinguishable from the original — a stale
 65	/// `SourceData` was served with no signal anything was wrong. A content hash
 66	/// closes this gap exactly: two different byte sequences essentially never
 67	/// hash to the same 64-bit `FxHasher` value (birthday-bound collision risk
 68	/// is negligible at this cache's `MAX_CACHE_ENTRIES` scale), and identical
 69	/// bytes always hash identically regardless of mtime/clock granularity.
 70	/// This trades away the old stat-only check's near-zero I/O cost — computing
 71	/// the hash requires the file's content, not just its metadata — but every
 72	/// call site already reads the full file on a miss to parse it anyway; `get`
 73	/// and `insert` both take that same content as a parameter instead of
 74	/// re-deriving a (now-unreliable) proxy for it, so no call site pays for an
 75	/// extra read this fix didn't already need.
 76	#[derive(Hash, Eq, PartialEq, Clone)]
 77	struct CacheKey {
 78	    path: Utf8PathBuf,
 79	    content_hash: u64,
 80	}
 81	
 82	fn hash_content(content: &str) -> u64 {
 83	    let mut hasher = rustc_hash::FxHasher::default();
 84	    hasher.write(content.as_bytes());
 85	    hasher.finish()
 86	}
