110	/// Maximum number of cached `.d.ts` entries allowed in memory/on disk.
111	const MAX_CACHE_ENTRIES: usize = 5000;
112	
113	/// Thread-safe DTS parse-result cache.
114	///
115	/// Keyed by `(path, content_hash)` — if the file's content hasn't changed,
116	/// the cached `SourceData` is returned directly without re-parsing.
117	pub struct DtsCache {
118	    store: DashMap<CacheKey, SourceData>,
119	    cache_dir: Utf8PathBuf,
120	    dirty: std::sync::atomic::AtomicBool,
121	    lookups: std::sync::atomic::AtomicU32,
122	    hits: std::sync::atomic::AtomicU32,
123	    load_diagnostic: Option<Diagnostic>,
124	}
125	
126	/// Why a cache on disk was not used.
127	enum LoadFailure {
128	    /// No cache yet, or one written by a different build: expected, so not reported.
129	    Absent,
130	    /// A cache from this build that could not be read.
131	    Unreadable(String),
132	}
133	
134	impl DtsCache {
135	    /// Load cache from disk.
136	    ///
137	    /// On any error (missing dir, a different build's cache, corrupt data) the cache starts empty and `insert` calls
138	    /// repopulate it. A cache from this build that can't be decoded is reported by `load_diagnostic`.
139	    ///
140	    /// `cache_dir` defaults to `node_modules/.cache/caliper-docgen/` relative
141	    /// to the current working directory.
142	    pub fn load_from_disk(cache_dir: Option<&Utf8Path>) -> Self {
143	        let dir =
144	            cache_dir.map(|p| p.to_owned()).unwrap_or_else(|| Utf8PathBuf::from("node_modules/.cache/caliper-docgen"));
145	
146	        let (store, load_diagnostic) = match Self::try_load(&dir) {
147	            Ok(store) => (store, None),
148	            Err(LoadFailure::Absent) => (DashMap::default(), None),
149	            Err(LoadFailure::Unreadable(reason)) => (
150	                DashMap::default(),
151	                Some(
152	                    Diagnostic::new(
153	                        DiagnosticSeverity::Info,
154	                        DiagnosticCode::IoError,
155	                        format!("Discarded the unreadable DTS cache at '{dir}': {reason}"),
156	                    )
157	                    .with_help("This run parsed every file and rewrites the cache; extraction is unaffected."),
158	                ),
159	            ),
160	        };
161	        Self {
162	            store,
163	            cache_dir: dir,
164	            dirty: std::sync::atomic::AtomicBool::new(false),
165	            lookups: std::sync::atomic::AtomicU32::new(0),
166	            hits: std::sync::atomic::AtomicU32::new(0),
167	            load_diagnostic,
168	        }
169	    }
170	
171	    fn try_load(dir: &Utf8Path) -> Result<DashMap<CacheKey, SourceData>, LoadFailure> {
172	        use serde::Deserialize as _;
173	
174	        let bytes = match std::fs::read(dir.join(DATA_FILE).as_std_path()) {
175	            Ok(bytes) => bytes,
176	            Err(error) if matches!(error.kind(), std::io::ErrorKind::NotFound | std::io::ErrorKind::NotADirectory) => {
177	                return Err(LoadFailure::Absent)
178	            }
179	            Err(error) => return Err(LoadFailure::Unreadable(error.to_string())),
180	        };
181	        let mut decoder = rmp_serde::Deserializer::new(bytes.as_slice());
182	        // A header that doesn't decode is a payload from an older layout; that is a different build too.
183	        match CacheHeader::deserialize(&mut decoder) {
184	            Ok(header) if header == CacheHeader::current() => {}
185	            _ => return Err(LoadFailure::Absent),
186	        }
187	        let entries = Vec::<(SerializableCacheKey, SourceData)>::deserialize(&mut decoder)
188	            .map_err(|error| LoadFailure::Unreadable(error.to_string()))?;
189	
190	        let map = DashMap::with_capacity(entries.len());
191	        for (k, v) in entries {
192	            map.insert(CacheKey::from(k), v);
193	        }
194	        Ok(map)
195	    }
196	
197	    /// Why the cache on disk could not be used, when that is worth reporting.
198	    pub fn load_diagnostic(&self) -> Option<&Diagnostic> {
199	        self.load_diagnostic.as_ref()
200	    }
201	
202	    /// `(lookups, hits)` since load: how many `.d.ts` files went through the cache and how many it answered.
203	    pub fn counts(&self) -> (u32, u32) {
204	        (self.lookups.load(std::sync::atomic::Ordering::Relaxed), self.hits.load(std::sync::atomic::Ordering::Relaxed))
205	    }
206	
207	    /// Look up cached `SourceData` for `path`, given its current content.
208	    ///
209	    /// Returns `None` if the file is not cached or its content hash has
210	    /// changed. `content` is a parameter rather than read internally because
211	    /// every call site already reads the file to parse it on a miss — taking
212	    /// content here means neither a hit nor a miss ever reads the file twice.
213	    pub fn get(&self, path: &Utf8Path, content: &str) -> Option<SourceData> {
214	        let key = self.key_for(path, content);
215	        self.lookups.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
216	        let hit = self.store.get(&key).map(|v| v.clone());
217	        if hit.is_some() {
218	            self.hits.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
219	        }
220	        hit
221	    }
222	
223	    /// Insert `data` into the cache, keyed by `path` + a hash of `content`.
224	    pub fn insert(&self, path: &Utf8Path, content: &str, data: SourceData) {
225	        let key = self.key_for(path, content);
226	        // Evict extra entries if cache size exceeds MAX_CACHE_ENTRIES
227	        if self.store.len() >= MAX_CACHE_ENTRIES {
228	            let keys_to_evict: Vec<CacheKey> = self.store.iter().take(100).map(|r| r.key().clone()).collect();
229	            for k in keys_to_evict {
230	                self.store.remove(&k);
231	            }
232	        }
233	        self.store.insert(key, data);
234	        self.dirty.store(true, std::sync::atomic::Ordering::Relaxed);
235	    }
236	
237	    /// Persist the cache to disk atomically (temp file + rename).
238	    ///
239	    /// Skips writing if the cache is clean (no inserts since load). Never
240	    /// panics — on failure, returns a `Diagnostic` describing what went
241	    /// wrong (cache persistence is best-effort and must not fail the
242	    /// extraction run) instead of failing silently. Severity is `Info`, not
243	    /// `Warning`: a `Warning` here would flip `docgen check --strict`'s exit
244	    /// code to 1 purely because caching failed, even though extraction
245	    /// output itself is entirely correct — the exact class of spurious
246	    /// exit-code flip this project has already fixed once (see the
247	    /// resolver's discarded-return-type-resolution fix).
248	    pub fn save_to_disk(&self) -> Option<Diagnostic> {
249	        if !self.dirty.load(std::sync::atomic::Ordering::Relaxed) {
250	            return None;
251	        }
252	        self.try_save().err().map(|reason| Diagnostic {
253	            severity: DiagnosticSeverity::Info,
254	            message: format!("Failed to persist the DTS cache to '{}': {reason}", self.cache_dir),
255	            file: None,
256	            line: None,
257	            column: None,
258	            help: Some("Check that the cache directory is writable. Extraction still succeeded; only caching for the next run was affected.".into()),
259	            code: DiagnosticCode::IoError,
260	            affects: Vec::new(),
261	        })
262	    }
263	
264	    fn try_save(&self) -> Result<(), String> {
265	        std::fs::create_dir_all(self.cache_dir.as_std_path()).map_err(|e| e.to_string())?;
266	
267	        // Collect into a serializable form.
268	        let entries: Vec<(SerializableCacheKey, SourceData)> =
269	            self.store.iter().map(|r| (SerializableCacheKey::from(r.key()), r.value().clone())).collect();
270	
271	        let header = CacheHeader::current();
272	        let mut bytes = rmp_serde::to_vec(&header).map_err(|e| e.to_string())?;
273	        bytes.extend(rmp_serde::to_vec(&entries).map_err(|e| e.to_string())?);
274	
275	        write_atomic(&self.cache_dir, DATA_FILE, &bytes)?;
276	
277	        // For inspection only; loading trusts the payload's own header.
278	        let manifest = serde_json::json!({
279	            "schema": header.schema,
280	            "version": header.version,
281	            "fingerprint": header.fingerprint,
282	            "entry_count": entries.len(),
283	        });
284	        let manifest_json = serde_json::to_string_pretty(&manifest).map_err(|e| e.to_string())?;
285	        write_atomic(&self.cache_dir, "manifest.json", manifest_json.as_bytes())?;
286	
287	        self.dirty.store(false, std::sync::atomic::Ordering::Relaxed);
288	        Ok(())
289	    }
290	
291	    // ── Helpers ──────────────────────────────────────────────────────────────
292	
293	    /// Builds the cache key from the file's path and a hash of its content —
294	    /// see `CacheKey`'s doc comment for why this replaced mtime+size.
295	    fn key_for(&self, path: &Utf8Path, content: &str) -> CacheKey {
296	        CacheKey { path: path.to_owned(), content_hash: hash_content(content) }
297	    }
298	}
