150	/// Parse-or-load-from-cache a single `.d.ts` file and merge it into `global`,
151	/// draining any diagnostics the parse produced into `diagnostics` first —
152	/// matching how the main per-project-file loop (Phase 3) already handles this.
153	/// Shared by the Full-mode `@types/react` merge (Phase 3.5) and the ambient
154	/// `lib.d.ts` merge (Phase 3.6), which previously each merged the parsed data
155	/// directly with no diagnostics drain at all: an excessive-nesting trip or a
156	/// parse error while parsing either file would have been silently discarded,
157	/// since `GlobalSourceData` itself has no diagnostics field to catch it later.
158	pub(super) fn merge_cached_dts_file(
159	    path: &Utf8Path,
160	    cache: &DtsCache,
161	    global: &mut GlobalSourceData,
162	    diagnostics: &mut Vec<Diagnostic>,
163	) {
164	    // An unreadable file is reported and skipped; parsing "" instead would cache an empty result under this path.
165	    let source = match std::fs::read_to_string(path) {
166	        Ok(source) => source,
167	        Err(error) => {
168	            diagnostics.push(Diagnostic::io_read_error(path, &error));
169	            return;
170	        }
171	    };
172	    let mut data = match cache.get(path, &source) {
173	        Some(cached) => cached,
174	        None => {
175	            let data = crate::extractor::parse_file(path, &source);
176	            cache.insert(path, &source, data.clone());
177	            data
178	        }
179	    };
180	    diagnostics.append(&mut data.diagnostics);
181	    // These files exist to resolve types, not to document components: `@types/react`'s
182	    // own `class PureComponent<P, ...> extends Component<P, ...>` otherwise matches the
183	    // class-component detector and surfaces as a 0-prop component plus an unresolvable `P`.
184	    data.component_mappings.clear();
185	    global.merge(path, data);
186	}
