188	/// Canonicalize `src_dirs`' first entry to use as the "from" directory for
189	/// resolving @types/react and TypeScript's own lib.d.ts files — must match
190	/// what discovered file paths look like (always absolute — the `ignore`
191	/// walker absolutizes them regardless of whether --src was given as relative
192	/// or absolute), since the resolver looks this same specifier up again
193	/// per-component relative to each file's own absolute directory. A relative
194	/// src_dirs entry has too few path components for oxc_resolver's ancestor
195	/// walk to ever reach the real node_modules tree, so it silently finds
196	/// nothing instead of the intended real package.
197	pub(super) fn canonicalize_first_src_dir(src_dirs: &[Utf8PathBuf]) -> Option<Utf8PathBuf> {
198	    src_dirs.first().and_then(|dir| std::fs::canonicalize(dir).ok()).and_then(|p| Utf8PathBuf::from_path_buf(p).ok())
199	}
