201	/// Resolve `mappings` in parallel. The whole closure body is wrapped in `contain_panic` so one component's resolution
202	/// panicking degrades to a per-component diagnostic instead of poisoning the `.collect()` and losing every other
203	/// component. Shared by `extract()` and `WatchSession::update_file` so the two cannot drift.
204	pub(super) fn resolve_guarded(
205	    mappings: &[&ComponentMapping],
206	    ctx: &ResolutionContext,
207	) -> Vec<(ComponentEntry, Vec<Diagnostic>, crate::resolver::Dependencies)> {
208	    mappings
209	        .par_iter()
210	        .copied()
211	        .map(|mapping| {
212	            let label = format!("resolve:{}", mapping.component_name);
213	            crate::panic_guard::contain_panic(&label, || {
214	                #[cfg(test)]
215	                if mapping.component_name == RESOLVE_PANIC_TEST_SENTINEL {
216	                    panic!("simulated resolve-phase panic (test-only sentinel)");
217	                }
218	
219	                crate::resolver::resolve_component_tracked(mapping, ctx)
220	            })
221	            .unwrap_or_else(|diag| {
222	                let stub = ComponentEntry {
223	                    display_name: mapping.component_name.clone(),
224	                    file_path: mapping.file_path.clone(),
225	                    description: String::new(),
226	                    props: Default::default(),
227	                    inheritance: vec![],
228	                    notable_inherited: Default::default(),
229	                    discriminant_prop: None,
230	                    composes: vec![],
231	                    tags: Default::default(),
232	                    methods: vec![],
233	                };
234	                // A panicked resolution re-runs on any edit to its own file.
235	                let mut deps = crate::resolver::Dependencies::default();
236	                deps.files.insert(crate::path_key::PathKey::from(mapping.file_path.as_path()));
237	                (stub, vec![diag], deps)
238	            })
239	        })
240	        .collect()
241	}
