   243	/// Collect enum entries that are exported from their source files.
   244	pub(super) fn collect_public_enums(
   245	    global: &GlobalSourceData,
   246	) -> (std::collections::BTreeMap<String, Vec<EnumEntry>>, Vec<Diagnostic>) {
   247	    let mut result = std::collections::BTreeMap::new();
   248	    let mut origin: std::collections::BTreeMap<&str, &str> = std::collections::BTreeMap::new();
   249	    let mut diagnostics = Vec::new();
   250	
   251	    // Sorted so a name shared by two files resolves the same way on every run and in every input order.
   252	    let mut keys: Vec<&String> = global.enums.keys().collect();
   253	    keys.sort();
   254	
   255	    for scoped_key in keys {
   256	        // scoped_key = "{file_path}:{name}"; split from the right because a Windows path contains `:` too.
   257	        let Some((file_path_str, name)) = scoped_key.rsplit_once(':') else { continue };
   258	        let file_path = Utf8Path::new(file_path_str);
   259	        let is_exported = global.re_export_map.get(file_path).is_some_and(|exports| {
   260	            exports.iter().any(|e| matches!(e, LexedExport::LocalDeclaration { name: n, .. } if n == name))
   261	        });
   262	        if !is_exported {
   263	            continue;
   264	        }
   265	        if let Some(kept) = origin.get(name) {
   266	            diagnostics.push(Diagnostic {
   267	                severity: DiagnosticSeverity::Warning,
   268	                message: format!(
   269	                    "Enum `{name}` is exported from both {kept} and {file_path_str}; only the first is listed."
   270	                ),
   271	                file: Some(file_path_str.to_owned()),
   272	                line: None,
   273	                column: None,
   274	                help: Some("Rename one of the enums; the public enum map is keyed by bare name.".into()),
   275	                code: DiagnosticCode::DuplicateEnumName,
   276	                affects: Vec::new(),
   277	            });
   278	            continue;
   279	        }
   280	        origin.insert(name, file_path_str);
   281	        result.insert(name.to_owned(), global.enums[scoped_key].clone());
   282	    }
   283	
   284	    (result, diagnostics)
   285	}
