   430	/// Diagnostics merged by identity: an identical diagnostic reported while resolving many components is kept once,
   431	/// listing those components in `affects`.
   432	#[derive(Default)]
   433	struct DiagnosticSet {
   434	    index: FxHashMap<Diagnostic, usize>,
   435	    items: Vec<Diagnostic>,
   436	}
   437	
   438	impl DiagnosticSet {
   439	    fn add(&mut self, diagnostic: Diagnostic, component: Option<&str>) {
   440	        let at = match self.index.get(&diagnostic) {
   441	            Some(&at) => at,
   442	            None => {
   443	                self.index.insert(diagnostic.clone(), self.items.len());
   444	                self.items.push(diagnostic);
   445	                self.items.len() - 1
   446	            }
   447	        };
   448	        if let Some(key) = component {
   449	            self.items[at].affects.push(key.to_owned());
   450	        }
   451	    }
   452	
   453	    fn extend(&mut self, diagnostics: impl IntoIterator<Item = Diagnostic>, component: Option<&str>) {
   454	        for diagnostic in diagnostics {
   455	            self.add(diagnostic, component);
   456	        }
   457	    }
   458	
   459	    /// The diagnostics by file, position and message; run-wide ones (no file) first.
   460	    fn finish(self) -> Vec<Diagnostic> {
   461	        let mut items = self.items;
   462	        for diagnostic in &mut items {
   463	            diagnostic.affects.sort();
   464	            diagnostic.affects.dedup();
   465	        }
   466	        // Severity by explicit rank, worst first, and code by name: neither enum's declaration order is an ordering.
   467	        items.sort_by(|a, b| {
   468	            (&a.file, a.line, a.column, &a.message)
   469	                .cmp(&(&b.file, b.line, b.column, &b.message))
   470	                .then_with(|| severity_rank(&b.severity).cmp(&severity_rank(&a.severity)))
   471	                .then_with(|| format!("{:?}", a.code).cmp(&format!("{:?}", b.code)))
   472	                .then_with(|| a.help.cmp(&b.help))
   473	        });
   474	        items
   475	    }
   476	}
