   497	/// A typo'd `--src` (or a stale config `srcDirs`) must not silently produce an empty-but-valid-looking result.
   498	fn source_dir_diagnostics(options: &PipelineOptions) -> Vec<Diagnostic> {
   499	    let missing: Vec<&Utf8PathBuf> = options.src_dirs.iter().filter(|dir| !dir.as_std_path().is_dir()).collect();
   500	    let help = "Check --src (or docgen.config.ts srcDirs) for a typo'd or stale path.";
   501	    if options.src_dirs.is_empty() {
   502	        return vec![Diagnostic::new(
