   506	        )
   507	        .with_help("Set --src (or docgen.config.ts srcDirs) to at least one directory to scan.")];
   508	    }
   509	    if missing.len() == options.src_dirs.len() {
   510	        let mut diag = Diagnostic::new(
   511	            DiagnosticSeverity::Error,
   512	            DiagnosticCode::IoError,
   513	            format!(
   514	                "None of the configured source directories exist: {}",
   515	                options.src_dirs.iter().map(|dir| dir.as_str()).collect::<Vec<_>>().join(", ")
   516	            ),
   517	        )
   518	        .with_help(help);
   519	        if let Some(first) = options.src_dirs.first() {
   520	            diag = diag.with_file(first.to_string());
