     2	//!
     3	//! Cache validity is based on a content hash of the file's actual bytes, not
     4	//! mtime/size (see `CacheKey`'s doc comment for why that was replaced).
     5	//! The payload starts with a `CacheHeader`; a header that doesn't match the
     6	//! running build (schema, crate version, source fingerprint) discards the whole cache.
     7	//!
     8	//! The cache never panics — load failures degrade gracefully to an empty
     9	//! state, and save failures are reported via a `Diagnostic` (see
    10	//! `save_to_disk`) rather than swallowed.
    11	
    12	use camino::{Utf8Path, Utf8PathBuf};
    13	use dashmap::DashMap;
    14	use serde::{Deserialize, Serialize};
    15	use std::hash::Hasher;
    16	
    17	use crate::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity, SourceData};
