   291	    // ── Helpers ──────────────────────────────────────────────────────────────
   292	
   293	    /// Builds the cache key from the file's path and a hash of its content —
   294	    /// see `CacheKey`'s doc comment for why this replaced mtime+size.
   295	    fn key_for(&self, path: &Utf8Path, content: &str) -> CacheKey {
   296	        CacheKey { path: path.to_owned(), content_hash: hash_content(content) }
   297	    }
