   256	/// Where TypeScript's lib files were found; see [`resolve_ts_lib_paths`].
   257	#[derive(Debug, Default, PartialEq)]
   258	pub struct TsLibs {
   259	    pub paths: Vec<String>,
   260	    /// Set when `typescript` is installed but lacks a lib file. Only the pipeline reports it, not the other callers.
"}}}

