//! Named type resolution.

use camino::Utf8Path;
use compact_str::CompactString;

use crate::known::{push_known_opaque_diagnostic, KnownPatternResult};
use crate::react_types;
use crate::types::*;

use super::alias::resolve_type_alias_type;
use super::collected::resolve_collected_type;
use super::import::{lookup_ambient_global, AmbientGlobalLookup};
use super::react::react_type_to_prop_type;
use super::{ResolutionContext, MAX_DEPTH};

/// Cycle-detecting entry point — see `ResolveState::named_in_progress`'s doc
/// comment for why this can't reuse chain.rs's permanent `visited` set or
/// mimic its clone-per-branch pattern. Delegates the actual resolution to
/// `resolve_named_uncycled` so every one of that function's many early
/// returns doesn't need to remember to remove the in-progress key itself.
#[allow(clippy::too_many_arguments)]
pub(super) fn resolve_named(
    name: &CompactString,
    args: &[CollectedType],
    consuming_file: &Utf8Path,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
    depth: u8,
) -> PropType {
    // Structural arguments: their display form abbreviates object types to `{ ... }`, which collided distinct
    // instantiations into a false cycle.
    let visit_key: CompactString = format!("{}:{}<{:?}>", consuming_file, name, args).into();

    if !state.named_in_progress.insert(visit_key.clone()) {
        state.diagnostics.push(Diagnostic {
            severity: DiagnosticSeverity::Info,
            message: format!(
                "Circular type reference detected resolving '{}' in '{}' — stopping here to avoid infinite recursion",
                name, consuming_file
            ),
            file: Some(consuming_file.to_string()),
            line: None,
            column: None,
            help: Some("This type (directly or indirectly) references itself.".into()),
            code: DiagnosticCode::CircularReference,
            affects: Vec::new(),
        });
        return OpaqueDetail::new(name.to_string(), OpaqueReason::DepthExceeded);
    }

    let result = resolve_named_uncycled(name, args, consuming_file, ctx, state, depth);
    state.named_in_progress.remove(&visit_key);
    result
}

#[allow(clippy::too_many_arguments)]
fn resolve_named_uncycled(
    name: &CompactString,
    args: &[CollectedType],
    consuming_file: &Utf8Path,
    ctx: &ResolutionContext,
    state: &mut ResolveState,
    depth: u8,
) -> PropType {
    if depth > MAX_DEPTH {
        let diag = super::max_depth_diagnostic(&format!("named type '{}'", name), consuming_file);
        return OpaqueDetail::give_up(state, name.to_string(), OpaqueReason::DepthExceeded, diag);
    }

    // ── 1. React builtin check ────────────────────────────────────────────────
    let lookup_name = name.strip_prefix("React.").unwrap_or(name.as_str());
    if react_types::is_react_builtin(lookup_name, &ctx.extra_builtins) {
        return react_type_to_prop_type(name.as_str(), args, consuming_file, ctx, state, depth);
    }

    // Resolve type arguments eagerly — needed for both source lookups and known patterns.
    let resolved_args: Vec<PropType> =
        args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();

    // ── 2-5. Try the project's own source before a known-pattern shortcut ────
    // See `resolver::precedence` — the shared, single-source-of-truth order.
    let (canonical_file, canonical_name, matched) =
        super::precedence::resolve_source_defined_or_known(name.as_str(), &resolved_args, consuming_file, ctx, state);

    match matched {
        Some(super::precedence::SourceOrKnownMatch::TypeAlias { matched_key, alias }) => {
            // The call site's arguments replace the alias's declared parameters (`type Foo<TData> = ...` used as
            // `Foo<string>`). Parameters left unfilled stay expected, unexpandable placeholders, not unresolvable
            // types, so they are registered for step 7 below.
            let Some(params) = ctx.named_types.lookup_type_alias_params(&canonical_file, &matched_key) else {
                return resolve_type_alias_type(&alias, ctx, state, depth);
            };
            state.in_scope_type_params.extend(params.iter().cloned());
            if args.is_empty() {
                return resolve_type_alias_type(&alias, ctx, state, depth);
            }
            let subst = super::substitute::build_substitution(params, args, consuming_file, &mut state.diagnostics);
            return resolve_type_alias_type(&super::substitute::substitute_alias(&alias, &subst), ctx, state, depth);
        }
        Some(super::precedence::SourceOrKnownMatch::Interface(_)) => {
            // At the prop-TYPE level (not chain level), an interface name is returned as Named.
            // Full prop expansion only happens at the component level via resolve_props_chain.
            return PropType::Named { name: name.clone(), args: resolved_args };
        }
        Some(super::precedence::SourceOrKnownMatch::Known(result)) => {
            return match result {
                KnownPatternResult::Type(pt) => {
                    if let PropType::Opaque(detail) = &pt {
                        push_known_opaque_diagnostic(
                            &mut state.diagnostics,
                            detail.reason(),
                            name.as_str(),
                            consuming_file,
                        );
                    }
                    pt
                }
                KnownPatternResult::Alias { name: alias_name } => {
                    // Follow the alias through resolve_named.
                    let alias_ct = CollectedType::Named { name: alias_name.as_str().into(), args: vec![] };
                    resolve_collected_type(&alias_ct, consuming_file, ctx, state, depth + 1)
                }
                KnownPatternResult::Props(_) => {
                    // Props result at type level — surface as Named.
                    PropType::Named { name: name.clone(), args: resolved_args }
                }
            };
        }
        None => {}
    }

    // ── 6. Silent no-op for well-known unresolvable types ────────────────────
    // TypeScript built-in utility types, DOM element types, and React HTML
    // attribute types all appear as prop types in real-world .d.ts files but
    // cannot be expanded without a type-checker. Return Named silently.
    let bare = name.strip_prefix("React.").unwrap_or(name.as_str());
    if super::is_ts_utility_type(bare)
        || matches!(
            bare,
            // TypeScript primitives used as type names
            "object" | "Object" | "Function" | "Symbol" | "BigInt"
            // React HTML attribute types (not in is_react_builtin; appear as prop types)
            | "HTMLAttributes" | "InputHTMLAttributes" | "TextareaHTMLAttributes"
            | "SelectHTMLAttributes" | "ButtonHTMLAttributes" | "AnchorHTMLAttributes"
            | "FormHTMLAttributes" | "LabelHTMLAttributes" | "ImgHTMLAttributes"
            | "VideoHTMLAttributes" | "AudioHTMLAttributes" | "DOMAttributes"
            | "AriaAttributes" | "HTMLInputTypeAttribute" | "HTMLAttributeReferrerPolicy"
            | "HTMLAttributeAnchorTarget" | "HTMLInputAutoCompleteAttribute"
            // React SVG/generic HTML prop types
            | "SVGAttributes" | "SVGProps" | "HTMLProps"
            // React component utility types
            | "ComponentRef" | "JSXElementConstructor"
        )
        || bare.ends_with("HTMLAttributes")
    {
        return PropType::Named { name: name.clone(), args: resolved_args };
    }
    // DOM element ref types (HTMLDivElement, HTMLInputElement, etc.)
    if bare.starts_with("HTML") && bare.ends_with("Element") {
        return PropType::Named { name: name.clone(), args: resolved_args };
    }
    if bare.starts_with("SVG") && bare.ends_with("Element") {
        return PropType::Named { name: name.clone(), args: resolved_args };
    }

    // ── 6.5 Enclosing generic's own type parameter — expected, not unresolvable ─
    if state.in_scope_type_params.contains(bare) {
        return PropType::Named { name: name.clone(), args: resolved_args };
    }

    // ── 6.7 TypeScript's own ambient globals (Date, RegExp, Element, ...) ────
    // Deliberately last: these never go through an import, so nothing earlier
    // ever had a reason to look here — but checked only after every other
    // shortcut above (including the well-known-TS-utility-type list at step 6)
    // has had its chance, since some names (Record, Partial, ...) are
    // themselves declared in these same lib files as mapped types this tool
    // can't expand, and step 6 already handles those correctly.
    if let Some(found) = lookup_ambient_global(ctx, bare) {
        return match found {
            AmbientGlobalLookup::Interface => PropType::Named { name: name.clone(), args: resolved_args },
            AmbientGlobalLookup::TypeAlias(alias) => {
                let alias = alias.clone();
                resolve_type_alias_type(&alias, ctx, state, depth)
            }
        };
    }

    // ── 7. Unresolvable — emit diagnostic, return Named ───────────────────────
    let location_note =
        super::unresolved_location_note(name.as_str(), consuming_file, &canonical_file, &canonical_name);

//! Evidence that a function renders, so a typed PascalCase function is a component and not a helper that happens to
//! take an object. A typed first parameter alone admits `FormatName = (u: User) => string`, `debounce((q: Row) => …)`
//! and selectors, so every rule that infers a component from a function asks this first.

use oxc_ast::ast::*;
use oxc_ast_visit::{walk, Visit};
use oxc_syntax::scope::ScopeFlags;

/// Why a function was judged not to render. Carried into the skip diagnostic.
pub(super) type NoRender = &'static str;

/// Names whose type, as a return annotation, means the function renders.
const ELEMENT_TYPE_NAMES: &[&str] = &["Element", "ReactElement", "ReactNode", "ReactPortal", "JSX"];

/// Callees that produce an element.
const ELEMENT_FACTORIES: &[&str] = &["createElement", "cloneElement", "jsx", "jsxs", "jsxDEV"];

fn rightmost_name<'n>(name: &'n TSTypeName<'_>) -> Option<&'n str> {
    match name {
        TSTypeName::IdentifierReference(id) => Some(id.name.as_str()),
        TSTypeName::QualifiedName(q) => Some(q.right.name.as_str()),
        _ => None,
    }
}

/// Whether a return type annotation names a renderable result: `JSX.Element`, `ReactNode`, `ReactElement`, a union
/// containing one, or `Promise` of one (async server components).
pub(super) fn type_renders(ty: &TSType<'_>) -> bool {
    match ty {
        TSType::TSTypeReference(r) => {
            let Some(name) = rightmost_name(&r.type_name) else { return false };
            if name == "Promise" {
                return r.type_arguments.as_ref().and_then(|a| a.params.first()).is_some_and(type_renders);
            }
            ELEMENT_TYPE_NAMES.contains(&name)
        }
        TSType::TSUnionType(u) => u.types.iter().any(type_renders),
        TSType::TSParenthesizedType(p) => type_renders(&p.type_annotation),
        _ => false,
    }
}

/// Looks for JSX, an element factory call, a top-level hook call (only components and hooks may call hooks, and a
/// PascalCase function is not a hook), or a top-level `return` of `null`, `children` or a call to a PascalCase function
/// (a component invoked directly, `return JoinList({...})`). Nested functions still count for JSX (a render callback),
/// but not for the top-level checks.
#[derive(Default)]
struct RenderFinder {
    renders: bool,
    nested: u32,
}

fn is_children(expr: &Expression<'_>) -> bool {
    match expr {
        Expression::Identifier(id) => id.name == "children",
        Expression::StaticMemberExpression(m) => m.property.name == "children",
        Expression::ParenthesizedExpression(p) => is_children(&p.expression),
        _ => false,
    }
}

fn callee_name<'n>(callee: &'n Expression<'_>) -> Option<&'n str> {
    match callee {
        Expression::Identifier(id) => Some(id.name.as_str()),
        Expression::StaticMemberExpression(m) => Some(m.property.name.as_str()),
        _ => None,
    }
}

fn is_hook_name(name: &str) -> bool {
    name.strip_prefix("use").is_some_and(|rest| rest.starts_with(|c: char| c.is_ascii_uppercase()))
}

fn returns_element_like(expr: &Expression<'_>) -> bool {
    match expr {
        Expression::NullLiteral(_) => true,
        Expression::CallExpression(call) => callee_name(&call.callee)
            .is_some_and(|n| n.starts_with(|c: char| c.is_ascii_uppercase()) || is_hook_name(n)),
        Expression::ParenthesizedExpression(p) => returns_element_like(&p.expression),
        _ => is_children(expr),
    }
}

impl<'a> Visit<'a> for RenderFinder {
    fn visit_jsx_element(&mut self, _it: &JSXElement<'a>) {
        self.renders = true;
    }

    fn visit_jsx_fragment(&mut self, _it: &JSXFragment<'a>) {
        self.renders = true;
    }

    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
        let callee = callee_name(&it.callee);
        if callee.is_some_and(|c| ELEMENT_FACTORIES.contains(&c) || (self.nested == 0 && is_hook_name(c))) {
            self.renders = true;
        }
        walk::walk_call_expression(self, it);
    }

    fn visit_return_statement(&mut self, it: &ReturnStatement<'a>) {
        if self.nested == 0 && it.argument.as_ref().is_some_and(returns_element_like) {
            self.renders = true;
        }
        walk::walk_return_statement(self, it);
    }

    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
        self.nested += 1;
        walk::walk_function(self, it, flags);
        self.nested -= 1;
    }

    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
        self.nested += 1;
        walk::walk_arrow_function_expression(self, it);
        self.nested -= 1;
    }
}

/// A function body: a block, or an arrow's single expression or block.
pub(super) enum Body<'b, 'a> {
    Block(&'b FunctionBody<'a>),
    Arrow(&'b ArrowFunctionBody<'a>),
}

/// The parts of a function that decide whether it renders.
pub(super) struct FunctionShape<'b, 'a> {
    pub generator: bool,
    pub return_type: Option<&'b TSTypeAnnotation<'a>>,
    pub body: Option<Body<'b, 'a>>,
}

impl<'b, 'a> FunctionShape<'b, 'a> {
    pub(super) fn of_arrow(f: &'b ArrowFunctionExpression<'a>) -> Self {
        Self { generator: false, return_type: f.return_type.as_deref(), body: Some(Body::Arrow(&f.body)) }
    }

    pub(super) fn of_function(f: &'b Function<'a>) -> Self {
        Self { generator: f.generator, return_type: f.return_type.as_deref(), body: f.body.as_deref().map(Body::Block) }
    }
}

/// `Ok` when the function renders; `Err` with the reason it does not.
pub(super) fn renders(shape: &FunctionShape<'_, '_>) -> Result<(), NoRender> {
    if shape.generator {
        return Err("is a generator");
    }
    if let Some(annotation) = shape.return_type {
        return if type_renders(&annotation.type_annotation) {
            Ok(())
        } else {
            Err("declares a return type that is not an element")
        };
    }
    let mut finder = RenderFinder::default();
    match &shape.body {
        None => return Err("has no body and no element return type"),
        Some(Body::Block(body)) => finder.visit_function_body(body),
        Some(Body::Arrow(body)) => {
            if let Some(expr) = body.as_expression() {
                if returns_element_like(expr) {
                    return Ok(());
                }
            }
            finder.visit_arrow_function_body(body);
        }
    }
    if finder.renders {
        Ok(())
    } else {
        Err("never renders: no JSX, element, hook call, or returned null, children or component call")
    }
}

//! One complete extraction state, and the single function that turns it into output.
//!
//! `extract()` builds a revision from scratch. Watch mode builds each next revision from the previous one: it re-parses
//! the changed file and re-resolves the components whose resolution read it, then publishes the whole revision at once.
//! Both paths produce output through `assemble`, so key disambiguation, plugin hooks, diagnostics and enums cannot
//! drift between them.

use std::collections::BTreeMap;
use std::sync::Arc;
use std::time::Instant;

use camino::{Utf8Path, Utf8PathBuf};
use rayon::prelude::*;
use rustc_hash::{FxHashMap, FxHashSet};

use crate::cache::DtsCache;
use crate::named_type_index::NamedTypeIndex;
use crate::resolver::{Dependencies, ResolutionContext};
use crate::types::output::severity_rank;
use crate::types::*;

use super::discover::{discover_files, is_source_file, should_skip};
use super::{
    canonicalize_first_src_dir, collect_public_enums, merge_cached_dts_file, resolve_guarded, HtmlAttributeMode,
    IncrementalUpdate, PipelineOptions,
};

/// A component's identity across revisions: its file, its name, and which same-named declaration in that file it is.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub(crate) struct ComponentId {
    file: Utf8PathBuf,
    name: String,
    ordinal: u32,
}

/// A resolved component, the diagnostics its resolution produced, and what that resolution depended on.
pub(crate) struct Resolved {
    entry: ComponentEntry,
    diagnostics: Vec<Diagnostic>,
    depends_on: Dependencies,
}

impl Resolved {
    /// Whether this resolution can differ after `change`.
    fn affected_by(&self, change: &Change<'_>) -> bool {
        self.depends_on.files.contains(change.file.as_str())
            || (change.created && self.depends_on.resolves_modules)
            || change.bare_names.iter().any(|name| self.depends_on.bare_names.contains(name.as_str()))
    }
}

/// One file's change, as far as dependency tracking cares.
struct Change<'c> {
    file: &'c Utf8Path,
    /// The file did not exist in the previous revision.
    created: bool,
    /// Enum and const-array names the file declared before or after the change.
    bare_names: FxHashSet<String>,
}

/// The bare names `file` declares in an enum or const-array map keyed `file:name`.
fn bare_names_declared<V>(file: &Utf8Path, map: &FxHashMap<String, V>) -> Vec<String> {
    let prefix = format!("{file}:");
    map.keys().filter_map(|key| key.strip_prefix(prefix.as_str()).map(str::to_owned)).collect()
}

pub(crate) struct Revision {
    pub(crate) id: u64,
    global: Arc<GlobalSourceData>,
    named_types: Arc<NamedTypeIndex>,
    ambient_global_files: Vec<Utf8PathBuf>,
    /// Source-directory and discovery diagnostics.
    head_diagnostics: Vec<Diagnostic>,
    /// Read, parse and file-plugin diagnostics, per source file.
    file_diagnostics: BTreeMap<Utf8PathBuf, Vec<Diagnostic>>,
    /// `@types/react` and TypeScript lib diagnostics.
    lib_diagnostics: Vec<Diagnostic>,
    /// The parse-cache save result.
    tail_diagnostics: Vec<Diagnostic>,
    resolved: FxHashMap<ComponentId, Arc<Resolved>>,
    /// The project's source files.
    files: Arc<FxHashSet<Utf8PathBuf>>,
    /// `.d.ts` files the cold run parsed or loaded from the parse cache, and how many the cache answered.
    dts_files_parsed: u32,
    dts_cache_hits: u32,
    duration_ms: u64,
    pub(crate) output: Arc<ExtractionOutput>,
    /// The output key each component was published under.
    keys: FxHashMap<ComponentId, String>,
}

/// The mapping identities of `global`, in output order: by file, then by position in the file.
fn component_ids<'g>(
    global: &'g GlobalSourceData,
    options: &PipelineOptions,
) -> Vec<(ComponentId, &'g ComponentMapping)> {
    let mut ordinals: FxHashMap<(&Utf8Path, &str), u32> = FxHashMap::default();
    let mut ids: Vec<(ComponentId, &ComponentMapping)> = global
        .component_mappings
        .iter()
        .filter(|m| !should_skip(&m.component_name, &options.exclude_prefixes))
        .map(|m| {
            let ordinal = ordinals.entry((m.file_path.as_path(), m.component_name.as_str())).or_insert(0);
            let id = ComponentId { file: m.file_path.clone(), name: m.component_name.clone(), ordinal: *ordinal };
            *ordinal += 1;
            (id, m)
        })
        .collect();
    ids.sort_by(|(a, ma), (b, mb)| (&a.file, ma.span_start, a.ordinal).cmp(&(&b.file, mb.span_start, b.ordinal)));
    ids
}

fn resolve_all(
    mappings: &[(ComponentId, &ComponentMapping)],
    ctx: &ResolutionContext,
) -> FxHashMap<ComponentId, Arc<Resolved>> {
    let borrowed: Vec<&ComponentMapping> = mappings.iter().map(|(_, m)| *m).collect();
    resolve_guarded(&borrowed, ctx)
        .into_iter()
        .zip(mappings)
        .map(|((entry, diagnostics, depends_on), (id, _))| {
            (id.clone(), Arc::new(Resolved { entry, diagnostics, depends_on }))
        })
        .collect()
}

impl Revision {
    /// Discover, parse, merge, resolve and assemble every source file.
    pub(crate) fn cold(options: &PipelineOptions, id: u64) -> Revision {
        let start = Instant::now();
        let mut head_diagnostics = source_dir_diagnostics(options);

        let cache = Arc::new(DtsCache::load_from_disk(options.cache_dir.as_deref()));
        head_diagnostics.extend(cache.load_diagnostic().cloned());

        let (src_files, discover_diagnostics) = discover_files(&options.src_dirs, &options.exclude_patterns);
        head_diagnostics.extend(discover_diagnostics);

        // The whole closure body is wrapped in `contain_panic` so one file's parse panicking degrades to a per-file
        // diagnostic instead of poisoning the `.collect()` and crashing the whole extraction run.
        let parsed: Vec<(Utf8PathBuf, SourceData, Option<Diagnostic>)> = src_files
            .par_iter()
            .map(|path| {
                let label = format!("parse:{path}");
                crate::panic_guard::contain_panic(&label, || {
                    #[cfg(test)]
                    if path.file_name() == Some(super::PARSE_PANIC_TEST_SENTINEL) {
                        panic!("simulated parse-phase panic (test-only sentinel)");
                    }
                    let (data, io_diag) = parse_source_file(path, &cache);
                    (path.clone(), data, io_diag)
                })
                .unwrap_or_else(|diag| (path.clone(), SourceData::default(), Some(diag)))
            })
            .collect();

        let mut global = GlobalSourceData::default();
        let mut file_diagnostics: BTreeMap<Utf8PathBuf, Vec<Diagnostic>> = BTreeMap::new();
        for (path, mut data, io_diag) in parsed {
            let mut diags: Vec<Diagnostic> = io_diag.into_iter().collect();
            diags.append(&mut data.diagnostics);
            diags.extend(options.plugins.run_on_file_extracted(&path, &mut data));
            if !diags.is_empty() {
                file_diagnostics.insert(path.clone(), diags);
            }
            global.merge(&path, data);
        }

        let mut lib_diagnostics = Vec::new();
        // Full HTML attribute mode needs @types/react's real interfaces merged before resolution, so the resolver can
        // look them up like any other interface instead of only recording an InheritedLayer.
        if options.html_attributes == HtmlAttributeMode::Full {
            let from_dir = canonicalize_first_src_dir(&options.src_dirs).unwrap_or_else(|| Utf8PathBuf::from("."));
            match crate::resolver::resolve_package_dts_path(&from_dir, "react") {
                Some(react_dts_path) => {
                    let react_dts_path = Utf8PathBuf::from(react_dts_path);
                    merge_cached_dts_file(&react_dts_path, &cache, &mut global, &mut lib_diagnostics);
                }
                None => lib_diagnostics.push(
                    Diagnostic::new(
                        DiagnosticSeverity::Warning,
                        DiagnosticCode::MissingTypeLibrary,
                        "HtmlAttributeMode::Full requested but @types/react could not be resolved",
                    )
                    .with_help("Check that @types/react is installed. Falling back to curated attributes."),
                ),
            }
        }
        // Ambient globals (Date, Element, ...) live in TS's lib files and are never imported, so merge them in every
        // mode. An install missing a lib file (TS 7 without its platform package) is reported here.
        if let Some(from_dir) = canonicalize_first_src_dir(&options.src_dirs) {
            let libs = crate::resolver::resolve_ts_lib_paths(&from_dir);
            lib_diagnostics.extend(libs.diagnostic);
            for lib_path in libs.paths {
                merge_cached_dts_file(&Utf8PathBuf::from(lib_path), &cache, &mut global, &mut lib_diagnostics);
            }
        }

        let global = Arc::new(global);
        let named_types = Arc::new(NamedTypeIndex::build(&global));
        let ambient_global_files = crate::resolver::compute_ambient_global_files(options);
        let ctx = ResolutionContext::new_with_cached_ambient_global_files(
            global.clone(),
            options,
            ambient_global_files.clone(),
            named_types.clone(),
        );
        let resolved = resolve_all(&component_ids(&global, options), &ctx);
        let files = Arc::new(src_files.into_iter().collect());

        let (dts_files_parsed, dts_cache_hits) = cache.counts();
        // Arc::try_unwrap succeeds because all rayon workers have finished.
        let tail_diagnostics: Vec<Diagnostic> = match Arc::try_unwrap(cache) {
            Ok(c) => c.save_to_disk(),
            Err(arc) => arc.save_to_disk(),
        }
        .into_iter()
        .collect();

