/// One file's change, as far as dependency tracking cares.
struct Change<'c> {
    file: &'c Utf8Path,
    /// The file did not exist in the previous revision.
    created: bool,
    /// Enum and const-array names the file declared before or after the change.
    bare_names: FxHashSet<String>,
}

