//! Plugin system for extending component prop extraction & post-processing.
//!
//! Inspired by `michi`'s zero-dep trait architecture and `callisto`'s modular design.
//! Plugins can hook into extraction events to transform AST data or enrich component entries.

use std::sync::Arc;

use crate::types::{ComponentEntry, SourceData};

/// Hook trait for docgen extension plugins.
pub trait DocgenPlugin: Send + Sync {
    /// Unique plugin name identifier.
    fn name(&self) -> &str;

    /// Invoked after AST extraction for a single file (`SourceData`).
    fn on_file_extracted(&self, _file_path: &camino::Utf8Path, _data: &mut SourceData) {}

    /// Invoked after a component has been fully resolved into a `ComponentEntry`.
    fn on_component_resolved(&self, _entry: &mut ComponentEntry) {}
}

impl std::fmt::Debug for dyn DocgenPlugin {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("DocgenPlugin").field("name", &self.name()).finish()
    }
}

/// A registry holding active plugins for a pipeline run.
#[derive(Debug, Default, Clone)]
pub struct PluginRegistry {
    plugins: Vec<Arc<dyn DocgenPlugin>>,
}

impl PluginRegistry {
    pub fn new() -> Self {
        Self { plugins: Vec::new() }
    }

    pub fn register<P: DocgenPlugin + 'static>(&mut self, plugin: P) {
        self.plugins.push(Arc::new(plugin));
    }

    pub fn register_arc(&mut self, plugin: Arc<dyn DocgenPlugin>) {
        self.plugins.push(plugin);
    }

    pub fn run_on_file_extracted(
        &self,
        file_path: &camino::Utf8Path,
        data: &mut SourceData,
    ) -> Vec<crate::types::Diagnostic> {
        let mut diagnostics = Vec::new();
        for plugin in &self.plugins {
            let label = format!("plugin:{}:on_file_extracted", plugin.name());
            if let Err(diag) = crate::panic_guard::contain_panic(&label, || plugin.on_file_extracted(file_path, data)) {
                diagnostics.push(diag);
            }
        }
        diagnostics
    }

    pub fn run_on_component_resolved(&self, entry: &mut ComponentEntry) -> Vec<crate::types::Diagnostic> {
        let mut diagnostics = Vec::new();
        for plugin in &self.plugins {
            let label = format!("plugin:{}:on_component_resolved", plugin.name());
            if let Err(diag) = crate::panic_guard::contain_panic(&label, || plugin.on_component_resolved(entry)) {
                diagnostics.push(diag);
            }
        }
        diagnostics
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::ComponentEntry;

    struct TestEnricherPlugin;

    impl DocgenPlugin for TestEnricherPlugin {
        fn name(&self) -> &str {
            "test-enricher"
        }

        fn on_component_resolved(&self, entry: &mut ComponentEntry) {
            entry.composes.push("TestEnricher".into());
        }
    }

    #[test]
    fn test_plugin_registry_hook() {
        let mut registry = PluginRegistry::new();
        registry.register(TestEnricherPlugin);

        let mut entry = ComponentEntry {
            display_name: "Button".into(),
            file_path: "src/Button.tsx".into(),
            props: Default::default(),
            description: String::new(),
            inheritance: vec![],
            notable_inherited: Default::default(),
            discriminant_prop: None,
            composes: vec![],
            tags: Default::default(),
            methods: vec![],
        };

        registry.run_on_component_resolved(&mut entry);
        assert_eq!(entry.composes, vec!["TestEnricher"]);
    }

    struct FileHookPlugin;
    impl DocgenPlugin for FileHookPlugin {
        fn name(&self) -> &str {
            "file-hook"
        }
        fn on_file_extracted(&self, _path: &camino::Utf8Path, data: &mut SourceData) {
            data.interfaces.insert(
                "HookIface".into(),
                crate::types::CollectedInterface {
                    name: "HookIface".into(),
                    file_path: "src/test.tsx".into(),
                    scoped_key: "src/test.tsx:HookIface".into(),
                    props: vec![],
                    extends: vec![],
                    description: String::new(),
                    tags: Default::default(),
                },
            );
        }
    }

    #[test]
    fn test_plugin_registry_multiple_plugins_chained() {
        let mut registry = PluginRegistry::new();
        registry.register(TestEnricherPlugin);
        registry.register_arc(std::sync::Arc::new(FileHookPlugin));

        let mut data = SourceData::default();
        registry.run_on_file_extracted(camino::Utf8Path::new("src/test.tsx"), &mut data);
        assert!(data.interfaces.contains_key("HookIface"));
    }

    #[test]
    fn a_panicking_plugin_is_contained_and_tagged_with_its_name_others_still_run() {
        struct PanickingPlugin;
        impl DocgenPlugin for PanickingPlugin {
            fn name(&self) -> &str {
                "panicking-plugin"
            }
            fn on_component_resolved(&self, _entry: &mut ComponentEntry) {
                panic!("boom");
            }
        }

        let mut registry = PluginRegistry::new();
        registry.register(PanickingPlugin);
        registry.register(TestEnricherPlugin);

        let mut entry = ComponentEntry {
            display_name: "Button".into(),
            file_path: "src/Button.tsx".into(),
            props: Default::default(),
            description: String::new(),
            inheritance: vec![],
            notable_inherited: Default::default(),
            discriminant_prop: None,
            composes: vec![],
            tags: Default::default(),
            methods: vec![],
        };

        let diagnostics = registry.run_on_component_resolved(&mut entry);

        assert_eq!(diagnostics.len(), 1, "expected exactly one diagnostic, from the panicking plugin");
        assert_eq!(diagnostics[0].code, crate::types::DiagnosticCode::InternalPanic);
        assert!(
            diagnostics[0].message.contains("panicking-plugin"),
            "diagnostic should name the panicking plugin, got {}",
            diagnostics[0].message
        );
        assert_eq!(
            entry.composes,
            vec!["TestEnricher"],
            "the second, well-behaved plugin should still run after the first one panicked"
        );
    }
}

//! Resolution of known generic type patterns.
//!
//! These are types that appear across many libraries and need special handling
//! because static analysis alone cannot fully resolve them, OR because their
//! full expansion is noise for docgen purposes.
//!
//! To add a new pattern: add a match arm. That's it.

use compact_str::CompactString;
use rustc_hash::FxHashMap;

use crate::types::*;

/// Result of recognizing a known type pattern.
pub enum KnownPatternResult {
    /// Pattern resolves to a set of props
    Props(Vec<ParsedProp>),
    /// Pattern is opaque — use this PropType directly
    Type(PropType),
    /// Pattern transparently delegates to another type name
    Alias { name: String },
}

/// Push a diagnostic for a `KnownPatternResult::Type` that resolved to
/// `PropType::Opaque`. `resolve_known` has no diagnostics channel of its own
/// (this module must not depend on `resolver`), so callers push this
/// themselves right after matching `KnownPatternResult::Type(PropType::Opaque
/// { .. })` — otherwise a recognized-but-unexpandable pattern (ThemingProps,
/// StylesApiProps, cva/tv without discoverable variants, …) degrades with no
/// trace at all, unlike every other opaque-producing path in the resolver.
pub fn push_known_opaque_diagnostic(
    diagnostics: &mut Vec<Diagnostic>,
    reason: &OpaqueReason,
    type_name: &str,
    file: &camino::Utf8Path,
) {
    let why = match reason {
        OpaqueReason::RuntimeDependent { function_name } => {
            format!("depends on '{function_name}' at runtime")
        }
        OpaqueReason::ModuleAugmentation => "depends on a module augmentation this tool doesn't evaluate".to_string(),
        OpaqueReason::ConditionalType => "is a conditional type".to_string(),
        OpaqueReason::MappedType => "is a mapped type".to_string(),
        OpaqueReason::UnresolvableImport { specifier } => format!("could not be resolved from '{specifier}'"),
        OpaqueReason::PandaCodegenMissing => "depends on PandaCSS's generated styled-system output".to_string(),
        OpaqueReason::DepthExceeded => "exceeded the maximum resolution depth".to_string(),
        OpaqueReason::IndexedAccess { expression } => format!("is an indexed access type ('{expression}')"),
        OpaqueReason::TemplateLiteral { expression } => format!("is a template literal type ('{expression}')"),
        OpaqueReason::MultiParamFunction => "is a function type with more than one parameter".to_string(),
        OpaqueReason::UnsupportedExpression => "is a type expression this tool doesn't recognize".to_string(),
    };
    diagnostics.push(Diagnostic {
        severity: DiagnosticSeverity::Info,
        message: format!("'{type_name}' {why} and can't be statically resolved — it will appear as opaque"),
        file: Some(file.to_string()),
        line: None,
        column: None,
        help: None,
        code: DiagnosticCode::OpaqueType,
        affects: Vec::new(),
    });
}

/// Attempt to resolve a named generic type as a known pattern.
///
/// Called by the resolver when it encounters a type like `SxProps<Theme>`
/// or `VariantProps<typeof buttonVariants>`.
///
/// Returns `None` if this type is not recognized — caller should continue
/// with normal resolution.
///
/// `enum_bare_index` is the resolver's precomputed bare-name → scoped-key
/// index over `global.enums` (see `ResolutionContext::enum_bare_index`) —
/// passed through explicitly rather than as part of a resolver-owned context
/// type, since this module must not depend on `resolver` (no reverse deps).
pub fn resolve_known(
    name: &str,
    args: &[PropType],
    global: &GlobalSourceData,
    enum_bare_index: &FxHashMap<CompactString, CompactString>,
) -> Option<KnownPatternResult> {
    match name {
        // ── Variant systems ──────────────────────────────────────────────────
        // class-variance-authority: VariantProps<typeof buttonVariants>
        // PandaCSS: RecipeVariantProps<typeof buttonStyle>
        // vanilla-extract: RecipeVariants<typeof buttonRecipe>
        // tailwind-variants: VariantProps<typeof tv(...)>
        "VariantProps" | "RecipeVariantProps" | "RecipeVariants" => {
            resolve_cva_variant_props(args, global, enum_bare_index)
        }

        // ── MUI styling ─────────────────────────────────────────────────────
        // SxProps is a massive conditional type — surface as opaque
        "SxProps" | "SystemStyleObject" | "SystemCssProperties" => Some(KnownPatternResult::Type(PropType::SxProps)),

        // ── MUI-specific ─────────────────────────────────────────────────────
        // OverridableStringUnion requires type checker — degrade gracefully
        "OverridableStringUnion" => {
            // First arg is the base union, second is the Overrides interface.
            if let Some(base) = args.first() {
                Some(KnownPatternResult::Type(PropType::Union(vec![
                    base.clone(),
                    OpaqueDetail::new("/* module augmentation */", OpaqueReason::ModuleAugmentation),
                ])))
            } else {
                Some(KnownPatternResult::Type(OpaqueDetail::new(
                    "OverridableStringUnion",
                    OpaqueReason::ModuleAugmentation,
                )))
            }
        }

        // ── React Aria ───────────────────────────────────────────────────────
        // RenderProps<ButtonRenderProps> → simplify to scalar className/style
        "RenderProps" => Some(KnownPatternResult::Props(render_props())),
        // SlotProps → { slot?: string | null }
        "SlotProps" => Some(KnownPatternResult::Props(vec![slot_prop()])),

        // ── Chakra / Ark / Styled System ────────────────────────────────────
        // HTMLChakraProps<'button'> → same as ComponentPropsWithoutRef<'button'>
        "HTMLChakraProps" | "HTMLArkProps" | "HTMLStyledProps" => html_attrs_from_first_arg(args),

        // ThemingProps is runtime-dependent on the chakra theme
        "ThemingProps" => Some(KnownPatternResult::Type(OpaqueDetail::new(
            "ThemingProps",
            OpaqueReason::RuntimeDependent { function_name: "chakra".into() },
        ))),

        // ── Mantine ─────────────────────────────────────────────────────────
        // StylesApiProps is runtime-dependent on createStyles
        "StylesApiProps" => Some(KnownPatternResult::Type(OpaqueDetail::new(
            "StylesApiProps",
            OpaqueReason::RuntimeDependent { function_name: "createStyles".into() },
        ))),

        // MantineColor/Size/Radius are string aliases — let resolver handle as Named
        "MantineColor" | "MantineSize" | "MantineRadius" => None,

        // ── React standard ───────────────────────────────────────────────────
        "PropsWithChildren" => props_with_children(args),
        "PropsWithRef" => props_with_ref(args),

        // ComponentPropsWithoutRef<'button'> or ComponentPropsWithoutRef<typeof X>
        "ComponentPropsWithoutRef" | "ComponentProps" | "ComponentPropsWithRef" => component_props(args),

        // ElementRef<typeof X> → opaque Ref
        "ElementRef" => Some(KnownPatternResult::Type(PropType::Ref { element: None })),

        // ── Unknown type names (including TS utility types like Partial/Omit/Pick —
        // structurally handled in resolver/alias.rs, silently no-op'd via
        // resolver::is_ts_utility_type otherwise) — caller continues normal resolution.
        _ => None,
    }
}

fn resolve_cva_variant_props(
    args: &[PropType],
    global: &GlobalSourceData,
    enum_bare_index: &FxHashMap<CompactString, CompactString>,
) -> Option<KnownPatternResult> {
    // The arg is typeof buttonVariants — a Named type reference to a cva() call result.
    // We stored the cva() call variants in global.enums during extraction.
    // Look them up and return as individual props.
    //
    // If we can't find the variants (e.g. they're imported from elsewhere),
    // return an Opaque rather than failing.

    match args.first() {
        Some(PropType::Named { name, .. }) => {
            // Look up by bare name via the precomputed index (O(1)) instead of
            // scanning every enum/cva/tv/recipe entry in the project with a
            // fresh `format!()` allocation per candidate.
            let name_str = name.as_str();
            let found = enum_bare_index.get(name_str).and_then(|key| global.enums.get_key_value(key.as_str()));

            match found {
                Some((_key, enum_entries)) => {
                    // Build one LiteralUnion prop per variant key found in enum entries.
                    // Group by variant key (the enum entry name acts as variant key).
                    // Each EnumEntry maps to a variant value; group all values for
                    // the same variant key into a LiteralUnion prop.
                    use std::collections::BTreeMap;
                    let mut variant_map: BTreeMap<String, Vec<String>> = BTreeMap::new();

                    for entry in enum_entries {
                        variant_map.entry(entry.name.clone()).or_default().push(entry.value.to_display_string());
                    }

                    if variant_map.is_empty() {
                        return Some(KnownPatternResult::Type(OpaqueDetail::new(
                            format!("VariantProps<typeof {}>", name_str),
                            OpaqueReason::RuntimeDependent { function_name: "cva".into() },
                        )));
                    }

                    // CVA/tv/defineRecipe VariantProps adds `| null` to every
                    // variant key (passing null opts out of the variant, using
                    // the default). Match what the TypeScript type system produces.
                    let props = variant_map
                        .into_iter()
                        .map(|(variant_key, values)| {
                            simple_prop(
                                &variant_key,
                                PropType::Union(vec![
                                    PropType::LiteralUnion { members: values, has_default: false },
                                    PropType::Null,
                                ]),
                                false,
                                "",
                            )
                        })
                        .collect();

                    Some(KnownPatternResult::Props(props))
                }
                None => {
                    // Variants not found in global data — degrade to opaque
                    Some(KnownPatternResult::Type(OpaqueDetail::new(
                        format!("VariantProps<typeof {}>", name_str),
                        OpaqueReason::RuntimeDependent { function_name: "cva".into() },
                    )))
                }
            }
        }
        _ => Some(KnownPatternResult::Type(OpaqueDetail::new(
            "VariantProps<...>",
            OpaqueReason::RuntimeDependent { function_name: "cva".into() },
        ))),
    }
}

fn render_props() -> Vec<ParsedProp> {
    // React Aria RenderProps<T> → simplify to these two props
    // Omit the function overload — noise for docgen
    vec![
        simple_prop("className", PropType::String, false, "CSS class name. Accepts a function receiving render state."),
        simple_prop(
            "style",
            PropType::CssProperties,
            false,

            global,
            named_types,
            ambient_global_files: self.ambient_global_files.clone(),
            head_diagnostics: self.head_diagnostics.clone(),
            file_diagnostics,
            lib_diagnostics: self.lib_diagnostics.clone(),
            tail_diagnostics: self.tail_diagnostics.clone(),
            resolved,
            files: Arc::new(files),
            dts_files_parsed: self.dts_files_parsed,
            dts_cache_hits: self.dts_cache_hits,
            duration_ms: self.duration_ms,
            output: Arc::new(empty_output()),
            keys: FxHashMap::default(),
        };
        next.assemble(options);

        let updated_components: Vec<(String, ComponentEntry)> = fresh_ids
            .iter()
            .filter_map(|id| {
                Some((next.keys.get(id)?.clone(), next.output.components.get(next.keys.get(id)?)?.clone()))
            })
            .collect();
        let removed_keys: Vec<String> =
            self.output.components.keys().filter(|key| !next.output.components.contains_key(*key)).cloned().collect();
        let mut affected_files: Vec<Utf8PathBuf> = fresh_ids.iter().map(|id| id.file.clone()).collect();
        affected_files.sort();
        affected_files.dedup();
        // The changed file's own diagnostics and those of every re-resolved component.
        let updated: FxHashSet<&str> = updated_components.iter().map(|(key, _)| key.as_str()).collect();
        let diagnostics: Vec<Diagnostic> = next
            .output
            .diagnostics
            .iter()
            .filter(|d| {
                d.file.as_deref() == Some(changed.as_str())
                    || d.affects.iter().any(|key| updated.contains(key.as_str()))
            })
            .cloned()
            .collect();
        let update = IncrementalUpdate {
            revision: next.id,
            updated_components: updated_components.iter().map(|(_, entry)| entry.clone()).collect(),
            updated_keys: updated_components.into_iter().map(|(key, _)| key).collect(),
            removed_keys,
            affected_files,
            diagnostics,
            duration_ms: start.elapsed().as_millis() as u64,
        };
        Some((next, update))
    }

    /// Build the public output from the revision: components keyed with the same disambiguation rule everywhere,
    /// plugin hooks applied, diagnostics in a stable order, public enums.
    fn assemble(&mut self, options: &PipelineOptions) {
        let mut diagnostics = DiagnosticSet::default();
        diagnostics.extend(self.head_diagnostics.iter().cloned(), None);
        for diags in self.file_diagnostics.values() {
            diagnostics.extend(diags.iter().cloned(), None);
        }
        diagnostics.extend(self.lib_diagnostics.iter().cloned(), None);

        let mut components = BTreeMap::new();
        let mut keys = FxHashMap::default();
        let mut seen_names: FxHashMap<String, u32> = FxHashMap::default();
        for (id, _) in component_ids(&self.global, options) {
            let Some(resolved) = self.resolved.get(&id) else { continue };
            let mut entry = resolved.entry.clone();
            let base_name = entry.display_name.clone();
            let count = seen_names.entry(base_name.clone()).or_insert(0);
            *count += 1;
            // The first occurrence of a name keeps it bare; later ones take their file path, which is unique per file.
            let key = if *count == 1 { base_name } else { format!("{} ({})", base_name, entry.file_path) };
            diagnostics.extend(options.plugins.run_on_component_resolved(&mut entry), Some(&key));
            let new_file_path = entry.file_path.clone();
            if let Some(previous) = components.insert(key.clone(), entry) {
                diagnostics.add(
                    Diagnostic::new(
                        DiagnosticSeverity::Warning,
                        DiagnosticCode::ComponentKeyCollision,
                        format!(
                            "Duplicate component key '{key}' — colliding file paths: previously '{}', now '{}'",
                            previous.file_path, new_file_path
                        ),
                    )
                    .with_file(new_file_path.to_string())
                    .with_help(
                        "Two resolved components produced the same display name and disambiguation key — only the \
                         later one is kept in the output. Check for overlapping src_dirs or a genuine duplicate \
                         declaration.",
                    ),
                    None,
                );
            }
            diagnostics.extend(resolved.diagnostics.iter().cloned(), Some(&key));
            keys.insert(id, key);
        }

        let (enums, enum_diagnostics) = collect_public_enums(&self.global);
        diagnostics.extend(enum_diagnostics, None);
        diagnostics.extend(self.tail_diagnostics.iter().cloned(), None);

        let components_extracted = components.len() as u32;
        self.output = Arc::new(ExtractionOutput {
            components,
            enums,
            diagnostics: diagnostics.finish(),
            stats: ExtractionStats {
                components_extracted,
                files_parsed: self.files.len() as u32,
                dts_files_parsed: self.dts_files_parsed,
                dts_cache_hits: self.dts_cache_hits,
                duration_ms: self.duration_ms,
                ..Default::default()
            },
        });
        self.keys = keys;
    }
}

/// Diagnostics merged by identity: an identical diagnostic reported while resolving many components is kept once,
/// listing those components in `affects`.
#[derive(Default)]
struct DiagnosticSet {
    index: FxHashMap<Diagnostic, usize>,
    items: Vec<Diagnostic>,
}

impl DiagnosticSet {
    fn add(&mut self, diagnostic: Diagnostic, component: Option<&str>) {
        let at = match self.index.get(&diagnostic) {
            Some(&at) => at,
            None => {
                self.index.insert(diagnostic.clone(), self.items.len());
                self.items.push(diagnostic);
                self.items.len() - 1
            }
        };
        if let Some(key) = component {
            self.items[at].affects.push(key.to_owned());
        }
    }

    fn extend(&mut self, diagnostics: impl IntoIterator<Item = Diagnostic>, component: Option<&str>) {
        for diagnostic in diagnostics {
            self.add(diagnostic, component);
        }
    }

    /// The diagnostics by file, position and message; run-wide ones (no file) first.
    fn finish(self) -> Vec<Diagnostic> {
        let mut items = self.items;
        for diagnostic in &mut items {
            diagnostic.affects.sort();
            diagnostic.affects.dedup();
        }
        // Severity by explicit rank, worst first, and code by name: neither enum's declaration order is an ordering.
        items.sort_by(|a, b| {
            (&a.file, a.line, a.column, &a.message)
                .cmp(&(&b.file, b.line, b.column, &b.message))
                .then_with(|| severity_rank(&b.severity).cmp(&severity_rank(&a.severity)))
                .then_with(|| format!("{:?}", a.code).cmp(&format!("{:?}", b.code)))
                .then_with(|| a.help.cmp(&b.help))
        });
        items
    }
}

/// Read and parse one source file, through the parse cache for `.d.ts`.
fn parse_source_file(path: &Utf8Path, cache: &DtsCache) -> (SourceData, Option<Diagnostic>) {
    let is_dts = path.as_str().ends_with(".d.ts");
    let (source, io_diag) = match std::fs::read_to_string(path) {
        Ok(s) => (s, None),
        Err(e) => (String::new(), Some(Diagnostic::io_read_error(path, &e))),
    };
    if is_dts {
        if let Some(cached) = cache.get(path, &source) {
            return (cached, io_diag);
        }
    }
    let data = crate::extractor::parse_file(path, &source);
    if is_dts {
        cache.insert(path, &source, data.clone());
    }
    (data, io_diag)
}

/// A typo'd `--src` (or a stale config `srcDirs`) must not silently produce an empty-but-valid-looking result.
fn source_dir_diagnostics(options: &PipelineOptions) -> Vec<Diagnostic> {
    let missing: Vec<&Utf8PathBuf> = options.src_dirs.iter().filter(|dir| !dir.as_std_path().is_dir()).collect();
    let help = "Check --src (or docgen.config.ts srcDirs) for a typo'd or stale path.";
    if options.src_dirs.is_empty() {
        return vec![Diagnostic::new(
            DiagnosticSeverity::Error,
            DiagnosticCode::IoError,
            "No source directories configured — src_dirs is empty",
        )
        .with_help("Set --src (or docgen.config.ts srcDirs) to at least one directory to scan.")];
    }
    if missing.len() == options.src_dirs.len() {
        let mut diag = Diagnostic::new(
            DiagnosticSeverity::Error,
            DiagnosticCode::IoError,
            format!(
                "None of the configured source directories exist: {}",
                options.src_dirs.iter().map(|dir| dir.as_str()).collect::<Vec<_>>().join(", ")
            ),
        )
        .with_help(help);
        if let Some(first) = options.src_dirs.first() {
            diag = diag.with_file(first.to_string());
        }
        return vec![diag];
    }
    missing
        .into_iter()
        .map(|dir| {
            Diagnostic::new(
                DiagnosticSeverity::Warning,
                DiagnosticCode::IoError,
                format!("Source directory does not exist: {dir}"),
            )
            .with_file(dir.to_string())
            .with_help(help)
        })
        .collect()
}

fn empty_output() -> ExtractionOutput {
    ExtractionOutput {
        components: BTreeMap::new(),
        enums: BTreeMap::new(),
        diagnostics: Vec::new(),
        stats: ExtractionStats::default(),
    }
}

//! Components declared through a wrapper call whose props travel as a type argument:
//! `const Button = polymorphicFactory<ButtonFactory>(...)`, `const Item = withContext<HTMLDivElement, ItemProps>(...)`.
//!
//! Nothing here names a library. A candidate is a PascalCase binding initialized with a generic call whose first
//! argument could plausibly be a component (a function, a tag name, another component). The props type is chosen from
//! the type arguments by shape, and only against declarations visible in the same file, so the rule needs no
//! cross-file state. Candidates are resolved when the file finishes, because `type ButtonFactory = ...` is often
//! declared after the call that uses it.

use std::collections::BTreeMap;

use oxc_ast::ast::*;
use oxc_span::Span;

use crate::types::{CollectedType, CollectedTypeAlias, ComponentMapping, DetectionRule, DiagnosticCode, TypeName};

use super::evidence::{renders, FunctionShape};
use super::SourceDataCollector;

/// One type argument of a candidate wrapper call.
pub(crate) struct WrapperTypeArg {
    /// The reference name and its stringified type arguments, when the argument is a plain type reference.
    reference: Option<(TypeName, Vec<CollectedType>)>,
}

/// A wrapper call waiting for the rest of the file to be seen.
pub(crate) struct PendingWrapper {
    name: String,
    /// The only evidence was a tag name, so the props must come from a factory payload.
    needs_payload: bool,
    type_args: Vec<WrapperTypeArg>,
    description: String,
    tags: BTreeMap<String, String>,
    span: Span,
}

/// Member that carries the props type inside a factory payload: `Factory<{ props: ButtonProps; ... }>`.
const PAYLOAD_PROPS_MEMBER: &str = "props";

/// Names that are DOM elements or refs rather than props, so they are never the props argument.
fn is_element_type(name: &str) -> bool {
    let bare = name.rsplit('.').next().unwrap_or(name);
    bare == "Element" || ((bare.starts_with("HTML") || bare.starts_with("SVG")) && bare.ends_with("Element"))
}

fn is_element_type_arg(ty: &TSType<'_>) -> bool {
    match ty {
        TSType::TSTypeReference(r) => match &r.type_name {
            TSTypeName::IdentifierReference(id) => is_element_type(id.name.as_str()),
            TSTypeName::QualifiedName(q) => is_element_type(q.right.name.as_str()),
            _ => false,
        },
        _ => false,
    }
}

fn is_component_reference(name: &str) -> bool {
    // `_Box` is Mantine's spelling of an implementation component.
    name.trim_start_matches(['_', '$']).starts_with(|c: char| c.is_ascii_uppercase())
}

/// How strongly the first argument says the call builds a component.
enum ArgumentEvidence {
    Sufficient,
    /// A tag name with no element type argument: a component only if a type argument is a factory payload.
    TagNeedsPayload,
}

/// Evidence that the call builds a component from its first argument: a function that renders (Mantine's
/// `factory<F>((props) => <Box />)`), a tag name next to an element type argument (`withContext<HTMLDivElement, P>("div")`)
/// or a factory payload (`tableElement<TableTrFactory>("tr")`), a reference to a component
/// (`withRootProvider<P>(Ark.Root)`), or a wrapped component (`polymorphic<P>(forwardRef(...))`). A tag string alone
/// also describes `makeLabel<P>("button")`, and a lowercase value describes a context default or a store, so neither
/// counts.
fn component_argument_evidence(callee: &str, call: &CallExpression<'_>) -> Result<ArgumentEvidence, &'static str> {
    if callee.rsplit('.').next() == Some("createContext") {
        return Err("creates a context");
    }
    let Some(first) = call.arguments.first().and_then(Argument::as_expression) else {
        return Err("has no argument that could be a component");
    };
    let element_type_arg = || call.type_arguments.as_ref().is_some_and(|a| a.params.iter().any(is_element_type_arg));
    let sufficient = |r: Result<(), &'static str>| r.map(|()| ArgumentEvidence::Sufficient);
    match first {
        Expression::ArrowFunctionExpression(f) => {
            sufficient(renders(&FunctionShape::of_arrow(f)).map_err(|_why| "is given a function that never renders"))
        }
        Expression::FunctionExpression(f) => {
            sufficient(renders(&FunctionShape::of_function(f)).map_err(|_why| "is given a function that never renders"))
        }
        Expression::StringLiteral(_) if element_type_arg() => Ok(ArgumentEvidence::Sufficient),
        Expression::StringLiteral(_) => Ok(ArgumentEvidence::TagNeedsPayload),
        Expression::Identifier(id) if is_component_reference(id.name.as_str()) => Ok(ArgumentEvidence::Sufficient),
        Expression::StaticMemberExpression(m) if is_component_reference(m.property.name.as_str()) => {
            Ok(ArgumentEvidence::Sufficient)
        }
        Expression::CallExpression(inner) if super::component::is_component_wrapper_call(inner) => {
            Ok(ArgumentEvidence::Sufficient)
        }
        _ => Err("is given an argument that is not a render function, a tag or a component reference"),
    }
}

impl<'src> SourceDataCollector<'src> {
    /// Record `const Name = callee<...>(first, ...)` as a candidate. Returns whether it was recorded.
    pub(super) fn try_record_wrapper_call<'a>(&mut self, decl: &super::component::Binding<'_, 'a>, name: &str) -> bool {
        let Some(init) = decl.init else { return false };
        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
        let Some(type_arguments) = call.type_arguments.as_ref() else { return false };
        let Some(callee) = self.extract_callee_name(call) else { return false };
        let needs_payload = match component_argument_evidence(&callee, call) {
            Ok(ArgumentEvidence::Sufficient) => false,
            Ok(ArgumentEvidence::TagNeedsPayload) => true,
            Err(reason) => {
                self.decline_reason = Some(format!("'{name}' is a generic call to '{callee}' that {reason}"));
                return false;
            }
        };
        let type_args: Vec<WrapperTypeArg> = type_arguments
            .params
            .iter()
            .map(|ty| WrapperTypeArg { reference: self.extract_type_name_from_type(ty) })
            .collect();
        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
        self.pending_wrappers.push(PendingWrapper {
            name: name.to_owned(),
            needs_payload,
            type_args,
            description,
            tags,
            span: decl.span,
        });
        true
    }

    /// Turn the recorded candidates into mappings, now that every declaration in the file is known.
    pub(super) fn promote_wrapper_calls(&mut self) {
        for pending in std::mem::take(&mut self.pending_wrappers) {
            if self.data.component_mappings.iter().any(|m| m.component_name == pending.name) {
                continue;
            }
            let selected = self
                .select_wrapper_props(&pending.type_args)
                .filter(|(_, _, from_payload)| *from_payload || !pending.needs_payload);
            let Some((props_name, props_args, _)) = selected else {
                self.record_skip(
                    DiagnosticCode::SkippedCandidate,
                    format!(
                        "'{}' looks like a component built by a wrapper call, but none of its type arguments names {}",
                        pending.name,
                        if pending.needs_payload {
                            "a factory payload, which a tag-name argument needs"
                        } else {
                            "a props type declared in this file or ending in Props"
                        }
                    ),
                    pending.span,
                );
                continue;
            };
            self.data.component_mappings.push(
                ComponentMapping::new(
                    pending.name,
                    props_name,
                    self.file_path.clone(),
                    pending.span.start,
                    pending.span.end,
                    DetectionRule::WrapperTypeArgument,
                )
                .with_props_type_args(props_args)
                .with_doc(pending.description, pending.tags),
            );
        }
    }

    /// Pick the props type from a wrapper call's type arguments, last first (the props usually follow the element).
    /// The third field says whether the props came from a factory payload.
    fn select_wrapper_props(&self, type_args: &[WrapperTypeArg]) -> Option<(TypeName, Vec<CollectedType>, bool)> {
        for arg in type_args.iter().rev() {
            let Some((name, args)) = &arg.reference else { continue };
            if is_element_type(name) {
                continue;
            }
            if let Some(props) = self.payload_props(name) {
                return Some((props, Vec::new(), true));
            }
            let declared_here = self.data.interfaces.contains_key(&self.scoped_key(name))
                || self.data.type_aliases.contains_key(&self.scoped_key(name));
            // A name from another file cannot be inspected here; only the props naming convention vouches for it.
            if declared_here || name.ends_with("Props") {
                return Some((name.clone(), args.clone(), false));
            }
        }
        None
    }

    /// `type ButtonFactory = Anything<{ props: ButtonProps; ... }>` yields `ButtonProps`.
    fn payload_props(&self, alias_name: &str) -> Option<TypeName> {
        let CollectedTypeAlias::Passthrough { target: CollectedType::Named { args, .. }, .. } =
            self.data.type_aliases.get(&self.scoped_key(alias_name))?
        else {
            return None;
        };
        args.iter().find_map(|arg| match arg {
            CollectedType::Object(fields) => fields.iter().find_map(|field| match &field.collected_type {
                CollectedType::Named { name, args } if field.name == PAYLOAD_PROPS_MEMBER && args.is_empty() => {
                    Some(name.clone())
                }
                _ => None,
            }),
            _ => None,
        })
    }
}

