/// Resolve a `CollectedType` as a props chain (for base types in aliases).
pub(super) fn resolve_base_as_chain(
    base: &CollectedType,
    file_path: &Utf8Path,
    mapping: &ComponentMapping,
    ctx: &ResolutionContext,
