/// Extra files some cases import from, written next to every case's source.
const SUPPORT: &[(&str, &str)] = &[
    ("barrel/index.ts", "export type { Shared } from \"./shared\";\n"),
    ("barrel/shared.ts", "export interface Shared { shared?: string }\n"),
    ("barrel2/index.ts", "import type { Imported } from \"./shared\";\nexport type { Imported };\n"),
    ("barrel2/shared.ts", "export interface Imported { imported?: string }\n"),
];

fn run(case: &Case) -> BTreeMap<String, Vec<String>> {
    let tmp = tempfile::TempDir::new().unwrap();
    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(tmp.path()).unwrap()).unwrap();
    for (name, body) in SUPPORT {
        let path = root.join(name);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, body).unwrap();
    }
    // `./barrel` in the case source resolves from the case file's directory.
    std::fs::write(
        root.join("case.tsx"),
        case.source.replace("\"./barrel\"", "\"./barrel/index\"").replace("\"./barrel2\"", "\"./barrel2/index\""),
    )
    .unwrap();
    let options =
        PipelineOptions { src_dirs: vec![root.clone()], cache_dir: Some(root.join(".cache")), ..Default::default() };
    extract(&options)
        .components
        .into_iter()
        .map(|(name, entry)| (name, entry.props.keys().cloned().collect()))
        .collect()
}

#[test]
fn every_declaration_shape_yields_exactly_the_expected_components_and_props() {
    let mut failures = Vec::new();
    for case in CASES {
        let got = run(case);
        let want: BTreeMap<String, Vec<String>> = case
            .expect
            .iter()
            .map(|(name, props)| ((*name).to_owned(), props.iter().map(|p| (*p).to_owned()).collect()))
            .collect();
        if got != want {
            failures.push(format!("{}:\n    want {want:?}\n    got  {got:?}", case.shape));
        }
    }
    assert!(failures.is_empty(), "shape regressions:\n{}", failures.join("\n"));
}

use std::fmt;

use serde::{Deserialize, Serialize};

/// A non-fatal issue discovered during extraction.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Diagnostic {
    pub severity: DiagnosticSeverity,
    pub message: String,
    pub file: Option<String>,
    pub line: Option<u32>,
    pub column: Option<u32>,
    pub help: Option<String>,
    pub code: DiagnosticCode,
    /// Output keys of the components whose resolution reported this diagnostic, sorted. Empty for diagnostics about a
    /// file or the run as a whole. Identical diagnostics from many components are reported once, listing them all.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub affects: Vec<String>,
}

impl fmt::Display for Diagnostic {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let Some(file) = &self.file {
            write!(f, "{file}: ")?;
        }
        write!(f, "{}", self.message)
    }
}

impl std::error::Error for Diagnostic {}

impl Diagnostic {
    /// A diagnostic with no file, position or help; add them with the `with_*` methods.
    pub fn new(severity: DiagnosticSeverity, code: DiagnosticCode, message: impl Into<String>) -> Diagnostic {
        Diagnostic {
            severity,
            message: message.into(),
            file: None,
            line: None,
            column: None,
            help: None,
            code,
            affects: Vec::new(),
        }
    }

    #[must_use]
    pub fn with_file(mut self, file: impl Into<String>) -> Diagnostic {
        self.file = Some(file.into());
        self
    }

    /// One-based line and column.
    #[must_use]
    pub fn with_position(mut self, line: u32, column: u32) -> Diagnostic {
        self.line = Some(line);
        self.column = Some(column);
        self
    }

    #[must_use]
    pub fn with_help(mut self, help: impl Into<String>) -> Diagnostic {
        self.help = Some(help.into());
        self
    }

    /// A file could not be read from disk (permission error, race with deletion, etc).
    pub fn io_read_error(path: &camino::Utf8Path, error: &std::io::Error) -> Diagnostic {
        Diagnostic {
            severity: DiagnosticSeverity::Error,
            message: format!("Failed to read '{path}': {error}"),
            file: Some(path.to_string()),
            line: None,
            column: None,
            help: Some("Check file permissions and that the file exists.".into()),
            code: DiagnosticCode::IoError,
            affects: Vec::new(),
        }
    }
}

#[non_exhaustive]
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum DiagnosticSeverity {
    Error,
    Warning,
    Info,
}

/// Machine-readable diagnostic codes for programmatic consumers.
#[non_exhaustive]
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum DiagnosticCode {
    UnresolvableImport,
    /// A generic type alias/interface was referenced with fewer type arguments
    /// than it declares parameters — the trailing, unfilled parameters were
    /// left as bare unresolved names in the substituted body.
    GenericArgumentMismatch,
    OpaqueType,
    MaxDepthExceeded,
    /// Deliberately unconstructed within this crate — reserved headroom for
    /// external consumers synthesizing their own [`Diagnostic`] outside the
    /// extraction pipeline (e.g. a wrapping tool reporting its own issue
    /// through this crate's diagnostic shape). Do not remove for being
    /// "unused"; nothing in `crates/core` or `crates/cli` is expected to
    /// construct it.
    Unknown,
    /// JSDoc @default conflicts with code default value — code value was used.
    JsDocDefaultMismatch,
    /// Default value is a runtime expression that could not be statically evaluated.
    ComputedDefault,
    /// Indexed access type (Type["key"]) that could not be resolved from known tables.
    IndexedAccessOpaque,
    /// Template literal type that could not be statically expanded.
    TemplateLiteralOpaque,
    /// Discriminated union detected — props merged with discriminant surfaced.
    DiscriminatedUnion,
    /// File could not be read — permission error or file missing.
    IoError,
    /// Source file exceeds the maximum type-nesting depth; skipped to avoid parser stack overflow.
    ExcessiveNesting,
    /// TypeScript syntax error reported by the parser.
    ParseError,
    /// An internal panic was caught and converted into a diagnostic instead
    /// of crashing the process (see ADR 0005). Never expected in normal
    /// operation — always a bug, filed with the panic's own message.
    InternalPanic,
    /// The extractor recognized an AST shape as a candidate (a type-alias utility
    /// invocation, a component-detector pattern) but it was malformed or
    /// incomplete in a way that made it unsupported — distinct from "wrong shape,
    /// not a candidate at all," which emits no diagnostic.
    SkippedCandidate,
    /// Two resolved components produced the identical output key (same display
    /// name, same disambiguated path suffix) — the later one silently overwrote
    /// the earlier in `ExtractionOutput::components`. Seen with 3+ same-named
    /// declarations in one file, or with overlapping `src_dirs` configs.
    ComponentKeyCollision,
    /// Two source files export an enum with the same name. The public `enums` map is keyed by bare name, so only the
    /// one from the lexicographically first file path is kept.
    DuplicateEnumName,
    /// A type references itself, directly or through other types; resolution stopped at the cycle. Distinct from
    /// `MaxDepthExceeded`, which means the nesting was merely too deep.
    CircularReference,
    /// `@types/react` or a TypeScript `lib.*.d.ts` file the run needs could not be found, as opposed to a type or
    /// import in the user's own code that failed to resolve.
    MissingTypeLibrary,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn io_read_error_reports_the_path_and_underlying_error() {
        let path = camino::Utf8Path::new("src/Button.tsx");
        let error = std::io::Error::new(std::io::ErrorKind::PermissionDenied, "permission denied");

        let diagnostic = Diagnostic::io_read_error(path, &error);

        assert_eq!(diagnostic.severity, DiagnosticSeverity::Error);
        assert_eq!(diagnostic.code, DiagnosticCode::IoError);
        assert_eq!(diagnostic.file.as_deref(), Some("src/Button.tsx"));
        assert!(diagnostic.message.contains("src/Button.tsx"));
        assert!(diagnostic.message.contains("permission denied"));
    }

    #[test]
    fn internal_panic_code_serializes_as_screaming_snake_case() {
        let diagnostic = Diagnostic {
            severity: DiagnosticSeverity::Error,
            message: "panic in rayon worker".into(),
            file: None,
            line: None,
            column: None,
            help: None,
            code: DiagnosticCode::InternalPanic,
            affects: Vec::new(),
        };
        let json = serde_json::to_string(&diagnostic).unwrap();
        assert!(json.contains("\"INTERNAL_PANIC\""), "expected INTERNAL_PANIC in {json}");
    }

    #[test]
    fn skipped_candidate_code_serializes_screaming_snake_case() {
        let json = serde_json::to_string(&DiagnosticCode::SkippedCandidate).unwrap();
        assert_eq!(json, "\"SKIPPED_CANDIDATE\"");
    }
}

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

use arc_swap::ArcSwapOption;
use camino::{Utf8Path, Utf8PathBuf};

use crate::types::*;

use super::revision::Revision;
use super::{IncrementalUpdate, PipelineOptions};

/// Canonicalize `path`, falling back to canonicalizing its parent directory
/// and rejoining the file name when the full path can't be resolved (e.g. the
/// file doesn't exist yet — created and then immediately edited before this
/// session ever saw it read successfully). Falls back to `path` unchanged only
/// when even the parent doesn't exist. Deliberately stable across a file's
/// create/delete transitions: the parent directory is what actually needs a
/// consistent identity across repeated `update_file` calls for the same file,
/// not the file itself.
fn canonicalize_best_effort(path: &Utf8Path) -> Utf8PathBuf {
    if let Ok(p) = std::fs::canonicalize(path.as_std_path()) {
        if let Ok(p) = Utf8PathBuf::from_path_buf(p) {
            return p;
        }
    }
    if let (Some(parent), Some(file_name)) = (path.parent(), path.file_name()) {
        if let Ok(p) = std::fs::canonicalize(parent.as_std_path()) {
            if let Ok(mut p) = Utf8PathBuf::from_path_buf(p) {
                p.push(file_name);
                return p;
            }
        }
    }
    path.to_owned()
}

/// Stateful session for incremental watch-mode extraction.
///
/// The session holds one immutable `Revision` at a time. `update_file` builds the next revision from the current one
/// (re-parsing the changed file, re-resolving the components whose resolution read it) and publishes it with a single
/// atomic store, so a reader always sees one complete revision, never parts of two. Writers are serialized; readers
/// never wait on them.
pub struct WatchSession {
    pub options: PipelineOptions,
    current: ArcSwapOption<Revision>,
    writer: Mutex<()>,
}

impl WatchSession {
    /// Create an empty WatchSession (call `initialize()` before first use).
    pub fn new(options: PipelineOptions) -> Self {
        Self { options, current: ArcSwapOption::empty(), writer: Mutex::new(()) }
    }

    /// Run a full cold extraction to populate this session.
    ///
    /// Idempotent — concurrent or repeated calls return the current snapshot without re-running extraction. Use
    /// `rebuild` to force a fresh extraction.
    pub fn initialize(&self) -> ExtractionOutput {
        let _writer = self.writer.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(current) = self.current.load_full() {
            return (*current.output).clone();
        }
        let revision = Arc::new(Revision::cold(&self.options, 1));
        let output = (*revision.output).clone();
        self.current.store(Some(revision));
        output
    }

    /// Discard the session's state and extract everything again.
    pub fn rebuild(&self) -> ExtractionOutput {
        let _writer = self.writer.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        let id = self.current.load().as_ref().map_or(1, |r| r.id + 1);
        let revision = Arc::new(Revision::cold(&self.options, id));
        let output = (*revision.output).clone();
        self.current.store(Some(revision));
        output
    }

    /// The published revision's number: 0 before `initialize`, then one higher for every change that produced a new
    /// revision. An update that leaves it unchanged changed nothing.
    pub fn revision(&self) -> u64 {
        self.current.load().as_ref().map_or(0, |revision| revision.id)
    }

    /// The current output: exactly what a cold `extract()` of the same files would return. Empty before `initialize`.
    pub fn snapshot(&self) -> ExtractionOutput {
        match self.current.load_full() {
            Some(revision) => (*revision.output).clone(),
            None => ExtractionOutput {
                components: BTreeMap::new(),
                enums: BTreeMap::new(),
                diagnostics: Vec::new(),
                stats: ExtractionStats::default(),
            },
        }
    }

    /// Apply one file change: an edit, a new file, or a deletion. A path that is not a source file of this project
    /// (outside every source directory, excluded, or not TypeScript) changes nothing.
    pub fn update_file(&self, changed: &Utf8Path) -> IncrementalUpdate {
